Below is a piece of js code. Your job is to predict the output of the function processInput given an input, which is a json-serializable dict. Here is the input:

{'contacts': [], 'bitrates': [100, 200], 'matrix': [[90, 110, 210], [130, 230, 330], [80, 180, 280]]}

Return the output dict as a json inside a json with the key 'code_output'. Here is the code:

```js
import {compareTwoStrings} from "string-similarity";
import {mean} from "mathjs";
export function processInput(input){
 const contacts=Array.isArray(input.contacts)?input.contacts:[];
 const bitrates=Array.isArray(input.bitrates)?input.bitrates:[];
 const matrix=Array.isArray(input.matrix)?input.matrix:[];
 const clusters=[];
 for(let i=0;i<contacts.length;i++){
  const c=contacts[i];let found=false;
  for(let j=0;j<clusters.length;j++){
   const d=clusters[j];
   if(compareTwoStrings(c.name,d.name)>0.8||compareTwoStrings(c.email,d.email)>0.8){
    if(c.name.length>d.name.length)d.name=c.name;
    if(c.email.length>d.email.length)d.email=c.email;
    found=true;break;
   }
  }
  if(!found)clusters.push({name:c.name,email:c.email});
 }
 const rows=matrix.length,cols=rows?matrix[0].length:0;
 const sm=[];
 for(let i=0;i<rows;i++){
  sm[i]=[];
  for(let j=0;j<cols;j++){
   const vals=[];
   for(let di=-1;di<=1;di++)for(let dj=-1;dj<=1;dj++){
    const ii=i+di,jj=j+dj;
    if(ii>=0&&ii<rows&&jj>=0&&jj<cols)vals.push(matrix[ii][jj]);
   }
   sm[i][j]=mean(vals);
  }
 }
 const adapted=[];
 const throughputs=[];
 const total=rows*cols;
 for(let i=0;i<total;i++)throughputs.push(sm[Math.floor(i/cols)][i%cols]);
 for(let k=0;k<throughputs.length;k++){
  const w=throughputs.slice(Math.max(0,k-2),k+1);
  const m=mean(w)*0.8;
  let chosen=bitrates[0]||0;
  for(let b of bitrates)if(b<=m&&b>chosen)chosen=b;
  adapted.push(chosen);
 }
 return {uniqueContacts:clusters,smoothedMatrix:sm,adaptedBitrates:adapted};
}
