import datetime
import decimal
import uuid
from typing import Annotated, List, Optional, Union, Literal

from pydantic import BaseModel, ConfigDict, Field, EmailStr, computed_field, model_validator


def to_camel(string: str) -> str:
    parts = string.split('_')
    return parts[0] + ''.join(word.capitalize() for word in parts[1:])


class Base(BaseModel):
    model_config = ConfigDict(alias_generator=to_camel, populate_by_name=True)


class Address(Base):
    street: str
    city: str
    zip_code: str
    country: str


class Client(Base):
    name: str
    email: EmailStr
    address: Address


class InvoiceItem(Base):
    description: str
    quantity: int = Field(gt=0)
    unit_price: decimal.Decimal = Field(gt=0)

    @computed_field
    def total_price(self) -> decimal.Decimal:
        return self.quantity * self.unit_price


class PercentDiscount(Base):
    type: Literal['percent']
    percent: decimal.Decimal = Field(gt=0, lt=1)


class FlatDiscount(Base):
    type: Literal['flat']
    amount: decimal.Decimal = Field(gt=0)


Discount = Annotated[Union[PercentDiscount, FlatDiscount], Field(discriminator='type')]


class TaxDetail(Base):
    category: str
    rate: decimal.Decimal = Field(gt=0, le=1)
    amount: decimal.Decimal = Field(ge=0)


class Invoice(Base):
    id: uuid.UUID
    date_issued: datetime.date
    date_due: Optional[datetime.date] = None
    payment_terms_days: Optional[int] = None
    client: Client
    items: List[InvoiceItem]
    discount: Optional[Discount] = None
    taxes: List[TaxDetail]
    currency: Literal['USD', 'EUR', 'GBP']
    status: Literal['draft', 'sent', 'paid', 'canceled']
    notes: Optional[str] = None

    @model_validator(mode='before')
    def compute_due(cls, values):
        date_issued = values.get('date_issued')
        terms = values.get('payment_terms_days')
        if date_issued and terms and not values.get('date_due'):
            values['date_due'] = date_issued + datetime.timedelta(days=terms)
        return values

    @computed_field
    def total_net(self) -> decimal.Decimal:
        net = sum(item.total_price for item in self.items)
        if self.discount:
            if getattr(self.discount, 'percent', None) is not None:
                net -= net * self.discount.percent
            elif getattr(self.discount, 'amount', None) is not None:
                net -= self.discount.amount
        return net

    @computed_field
    def total_tax(self) -> decimal.Decimal:
        return sum(t.amount for t in self.taxes)

    @computed_field
    def total_gross(self) -> decimal.Decimal:
        return self.total_net + self.total_tax

    @model_validator(mode='after')
    def validate_all(cls, model):
        if model.date_due and model.date_due < model.date_issued:
            raise ValueError('date_due must not be before date_issued')
        net = model.total_net
        for tx in model.taxes:
            expected = (net * tx.rate).quantize(decimal.Decimal('0.01'))
            if abs(tx.amount - expected) > decimal.Decimal('0.01'):
                raise ValueError(f"Invalid tax amount for {tx.category}: expected {expected}, got {tx.amount}")
        return model

