from enum import Enum
from typing import List, Dict, Union, Optional, Annotated, Literal
from decimal import Decimal
from uuid import UUID
from datetime import datetime
from pydantic import BaseModel, Field, model_validator

class Role(str, Enum):
    MANUFACTURER = 'Manufacturer'
    DISTRIBUTOR = 'Distributor'
    RETAILER = 'Retailer'
    INSPECTOR = 'Inspector'

class EventType(str, Enum):
    MANUFACTURE = 'manufacture'
    TRANSFER = 'transfer'
    INSPECTION = 'inspection'
    RETIREMENT = 'retirement'

class Stage(str, Enum):
    RAW = 'raw'
    IN_TRANSIT = 'in_transit'
    INSPECTED = 'inspected'
    RETIRED = 'retired'

class Product(BaseModel):
    product_id: UUID
    classification: str
    attributes: Dict[str, str]
    created_at: datetime

    model_config = {'extra': 'forbid'}

    @model_validator(mode='after')
    def check_attrs(cls, m):
        if not m.attributes:
            raise ValueError('product attributes must not be empty')
        return m

class Participant(BaseModel):
    id: UUID
    name: str
    role: Role

    model_config = {'extra': 'forbid'}

class Document(BaseModel):
    doc_id: UUID
    doc_type: str
    issued_at: datetime

    model_config = {'extra': 'forbid'}

class Location(BaseModel):
    lat: Decimal = Field(..., alias='latitude')
    lon: Decimal = Field(..., alias='longitude')
    name: str

    model_config = {'extra': 'forbid', 'populate_by_name': True}

    @model_validator(mode='after')
    def coords(cls, m):
        if not (-90 <= m.lat <= 90):
            raise ValueError('latitude out of range')
        if not (-180 <= m.lon <= 180):
            raise ValueError('longitude out of range')
        return m

class Batch(BaseModel):
    batch_id: UUID
    product: Product
    manufacture_date: datetime
    expiry_date: datetime
    quantity: Decimal = Field(..., gt=0)
    stage: Stage = Field(default=Stage.RAW)
    participants: List[UUID]
    docs: Optional[List[Document]] = None

    model_config = {'extra': 'forbid'}

    @model_validator(mode='after')
    def dates_and_stage(cls, m):
        if m.manufacture_date >= m.expiry_date:
            raise ValueError('batch manufacture_date must precede expiry_date')
        if m.stage != Stage.RAW:
            raise ValueError('initial batch stage must be RAW')
        if not m.participants:
            raise ValueError('batch participants must not be empty')
        return m

class ManufactureMeta(BaseModel):
    assembly_line: str
    quality_passed: bool

    model_config = {'extra': 'forbid'}

class TransferMeta(BaseModel):
    from_id: UUID
    to_id: UUID
    transport_mode: str

    model_config = {'extra': 'forbid'}

class InspectionMeta(BaseModel):
    inspector_id: UUID
    result: str

    model_config = {'extra': 'forbid'}

class RetirementMeta(BaseModel):
    reason: str
    timestamp: datetime

    model_config = {'extra': 'forbid'}

class EventBase(BaseModel):
    event_id: UUID
    batch_id: UUID
    event_type: EventType
    occurred_at: datetime
    location: Location

    model_config = {'extra': 'forbid'}

class ManufactureEvent(EventBase):
    event_type: Literal[EventType.MANUFACTURE]
    metadata: ManufactureMeta

class TransferEvent(EventBase):
    event_type: Literal[EventType.TRANSFER]
    metadata: TransferMeta

class InspectionEvent(EventBase):
    event_type: Literal[EventType.INSPECTION]
    metadata: InspectionMeta

class RetirementEvent(EventBase):
    event_type: Literal[EventType.RETIREMENT]
    metadata: RetirementMeta

Event = Annotated[
    Union[ManufactureEvent, TransferEvent, InspectionEvent, RetirementEvent],
    Field(discriminator='event_type')
]

class TraceLedger(BaseModel):
    ledger_id: UUID
    created_at: datetime
    products: Dict[UUID, Product]
    batches: Dict[UUID, Batch]
    participants: Dict[UUID, Participant]
    events: List[Event]

    model_config = {'extra': 'forbid'}

    @model_validator(mode='after')
    def consistency(cls, m):
        # verify event references known batches
        for e in m.events:
            if e.batch_id not in m.batches:
                raise ValueError(f'event {e.event_id} references unknown batch {e.batch_id}')
        # ensure first event per batch is manufacture
        events_by_batch: Dict[UUID, List[EventBase]] = {}
        for e in m.events:
            events_by_batch.setdefault(e.batch_id, []).append(e)
        for batch_id, evs in events_by_batch.items():
            first = min(evs, key=lambda x: x.occurred_at)
            if first.event_type != EventType.MANUFACTURE:
                raise ValueError(f'batch {batch_id} first event must be manufacture')
        # participant mapping consistency
        for b in m.batches.values():
            for pid in b.participants:
                if pid not in m.participants:
                    raise ValueError(f'batch {b.batch_id} has unknown participant {pid}')
        # validate transfer metadata participants
        for e in m.events:
            if isinstance(e, TransferEvent):
                meta = e.metadata
                if meta.from_id not in m.participants or meta.to_id not in m.participants:
                    raise ValueError(f'transfer event {e.event_id} has invalid participant ids')
        return m

```

