from datetime import time
import uuid
from typing import List, Optional

from pydantic import BaseModel, Field, ValidationError, model_validator


class GeoPoint(BaseModel):
    lat: float = Field(..., ge=-90, le=90)
    lon: float = Field(..., ge=-180, le=180)

    model_config = {'populate_by_name': True}


class TimeWindow(BaseModel):
    start: time
    end: time

    model_config = {'populate_by_name': True}

    @model_validator(mode='after')
    def check_order(self):
        if self.start >= self.end:
            raise ValidationError([{
                'loc': ('start',),
                'type': 'value_error.time_order',
                'msg': 'start must be before end',
                'input': self.start
            }], model=self.__class__)
        return self


class PricingTier(BaseModel):
    min_demand: int = Field(ge=0)
    max_demand: int = Field(ge=0)
    multiplier: float = Field(gt=0)
    window: TimeWindow

    model_config = {'populate_by_name': True}

    @model_validator(mode='after')
    def check_range(self):
        errors = []
        if self.min_demand > self.max_demand:
            errors.append({
                'loc': ('min_demand',),
                'type': 'value_error.demand_range',
                'msg': 'min_demand must be <= max_demand',
                'input': self.min_demand
            })
        if self.multiplier < 1:
            errors.append({
                'loc': ('multiplier',),
                'type': 'value_error.multiplier',
                'msg': 'multiplier should be >=1',
                'input': self.multiplier
            })
        if errors:
            raise ValidationError(errors, model=self.__class__)
        return self


class SurgeSchedule(BaseModel):
    name: str
    tiers: List[PricingTier]

    model_config = {'populate_by_name': True}

    @model_validator(mode='after')
    def check_tiers(self):
        sorted_tiers = sorted(self.tiers, key=lambda t: t.min_demand)
        for i in range(len(sorted_tiers) - 1):
            current = sorted_tiers[i]
            nxt = sorted_tiers[i + 1]
            if current.max_demand >= nxt.min_demand:
                raise ValidationError([{
                    'loc': ('tiers', i),
                    'type': 'value_error.overlap',
                    'msg': f'Tiers at index {i} and {i+1} overlap',
                    'input': current
                }], model=self.__class__)
        return self


class SurgeZone(BaseModel):
    id: uuid.UUID
    name: str
    polygon: List[GeoPoint]
    schedule: SurgeSchedule
    default_multiplier: float = Field(ge=1)
    metadata: Optional[dict] = None

    model_config = {'populate_by_name': True}

    @model_validator(mode='after')
    def check_polygon(self):
        pts = self.polygon
        if len(pts) < 4 or pts[0] != pts[-1]:
            raise ValidationError([{
                'loc': ('polygon',),
                'type': 'value_error.polygon_invalid',
                'msg': 'Polygon must have at least 4 points and start/end must match',
                'input': pts
            }], model=self.__class__)
        return self

