    use serde_json::{Value, from_str, to_string, Map, json};
    use std::io::{self, Read};

    fn adaptive_signage_controller(input: serde_json::Value) -> serde_json::Value {
    let road_segments = input["segments"].as_array().unwrap_or(&vec![]).clone();
    let weather_data = input["weather"].as_object().unwrap_or(&serde_json::Map::new()).clone();
    let time_of_day = input["time_minutes"].as_i64().unwrap_or(720);

    // Create matrix for segment-specific calculations
    let mut speed_matrix = vec![vec![0; 6]; road_segments.len().min(8)];

    // Extract weather factors
    let precipitation = weather_data.get("precipitation").and_then(|v| v.as_i64()).unwrap_or(0);
    let visibility = weather_data.get("visibility").and_then(|v| v.as_i64()).unwrap_or(10);
    let temperature = weather_data.get("temperature").and_then(|v| v.as_i64()).unwrap_or(20);
    let wind_speed = weather_data.get("wind_speed").and_then(|v| v.as_i64()).unwrap_or(0);

    // Fill matrix with complex calculations
    for (i, segment) in road_segments.iter().enumerate().take(8) {
        let base_speed = segment["base_limit"].as_i64().unwrap_or(60);
        let curvature = segment["curvature"].as_i64().unwrap_or(0);
        let elevation = segment["elevation"].as_i64().unwrap_or(0);
        let traffic_density = segment["traffic_density"].as_i64().unwrap_or(5);
        let segment_id = segment["id"].as_i64().unwrap_or(i as i64);

        // Calculate 6 different adjustment factors
        speed_matrix[i][0] = calculate_precipitation_factor(precipitation, curvature, base_speed);
        speed_matrix[i][1] = calculate_visibility_factor(visibility, segment_id, time_of_day);
        speed_matrix[i][2] = calculate_temperature_factor(temperature, elevation, segment_id);
        speed_matrix[i][3] = calculate_wind_factor(wind_speed, elevation, curvature);
        speed_matrix[i][4] = calculate_traffic_factor(traffic_density, time_of_day, segment_id);
        speed_matrix[i][5] = calculate_time_factor(time_of_day, segment_id, base_speed);
    }

    // Apply complex matrix transformations
    transform_adjustment_matrix(&mut speed_matrix, time_of_day);

    // Generate speed limits and warning levels
    let mut results = Vec::new();
    for (i, segment) in road_segments.iter().enumerate().take(8) {
        let segment_id = segment["id"].as_str().unwrap_or("unknown");
        let base_speed = segment["base_limit"].as_i64().unwrap_or(60);

        // Apply all adjustment factors
        let mut final_adjustment = 0;
        for j in 0..6 {
            final_adjustment += speed_matrix[i][j];
        }

        // Apply bit manipulation for extra complexity
        let bit_adjusted = ((final_adjustment & 0x0F) << 2) | ((final_adjustment & 0x30) >> 4);
        final_adjustment = (final_adjustment + bit_adjusted) / 2;

        // Calculate final speed and ensure it's within reasonable bounds
        let raw_speed = base_speed + final_adjustment;
        let final_speed = ((raw_speed + 2) / 5) * 5; // Round to nearest 5
        let bounded_speed = final_speed.max(20).min(100);

        // Calculate warning level based on adjustments
        let warning_level = calculate_warning_level(speed_matrix[i].clone(), precipitation, visibility);

        results.push(serde_json::json!({
            "segment_id": segment_id,
            "speed_limit": bounded_speed,
            "warning_level": warning_level,
            "message_code": generate_message_code(warning_level, final_adjustment, time_of_day)
        }));
    }

    serde_json::json!({
        "adaptive_limits": results,
        "system_status": calculate_system_status(&speed_matrix, precipitation, visibility),
        "next_update": calculate_next_update(time_of_day, precipitation, temperature)
    })
}

fn calculate_precipitation_factor(precip: i64, curvature: i64, base_speed: i64) -> i64 {
    let severity = (precip * 4) / (curvature + 1);
    let raw_adjustment = -((severity * 3) * base_speed) / 100;
    (raw_adjustment / 2) * 2 // Round to even number
}

fn calculate_visibility_factor(visibility: i64, segment_id: i64, time_minutes: i64) -> i64 {
    let time_modifier = if time_minutes < 360 || time_minutes > 1080 { 2 } else { 1 };
    let viz_impact = (10 - visibility.min(10)) * time_modifier;
    let segment_modifier = segment_id % 3 + 1;
    -((viz_impact * segment_modifier) / 2)
}

fn calculate_temperature_factor(temp: i64, elevation: i64, segment_id: i64) -> i64 {
    let effective_temp = temp - (elevation / 100);
    if effective_temp < 0 {
        -(((0 - effective_temp) * (segment_id % 5 + 1)) / 3)
    } else if effective_temp > 30 {
        -((effective_temp - 30) / 2)
    } else {
        0
    }
}

fn calculate_wind_factor(wind: i64, elevation: i64, curvature: i64) -> i64 {
    let exposure = (elevation / 50) + (curvature * 2);
    let wind_impact = (wind * exposure) / 10;
    -(wind_impact / 2) // Negative adjustment as wind increases
}

fn calculate_traffic_factor(density: i64, time_minutes: i64, segment_id: i64) -> i64 {
    let peak_factor = if (time_minutes > 420 && time_minutes < 540) || 
                         (time_minutes > 960 && time_minutes < 1080) { 2 } else { 1 };
    let crowding = density * peak_factor;
    let segment_specific = ((segment_id * 13) ^ (density * 7)) % 5 + 1;
    -((crowding * segment_specific) / 3)
}

fn calculate_time_factor(time_minutes: i64, segment_id: i64, base_speed: i64) -> i64 {
    let hour = (time_minutes / 60) % 24;
    let night_adjustment = if hour < 6 || hour > 21 { 
        ((segment_id % 5) - 2) * ((base_speed > 50) as i64 * 2 + 1)
    } else { 0 };
    night_adjustment
}

fn transform_adjustment_matrix(matrix: &mut Vec<Vec<i64>>, time_minutes: i64) {
    let rows = matrix.len();
    if rows == 0 { return; }

    // Apply row operations based on time
    let hour = (time_minutes / 60) % 24;
    for i in 0..rows {
        if (i + hour as usize) % 3 == 0 {
            // Shift row values
            let temp = matrix[i][0];
            for j in 0..5 {
                matrix[i][j] = matrix[i][j+1];
            }
            matrix[i][5] = temp;
        } else if (i + hour as usize) % 3 == 1 {
            // Amplify negative adjustments
            for j in 0..6 {
                if matrix[i][j] < 0 {
                    matrix[i][j] = (matrix[i][j] * 5) / 4;
                }
            }
        }
        // Apply segment connectivity rules - neighboring segments should have similar limits
        if i > 0 {
            let sum_prev = matrix[i-1].iter().sum::<i64>();
            let sum_curr = matrix[i].iter().sum::<i64>();
            let diff = (sum_curr - sum_prev).abs();
            if diff > 15 {
                let adjustment = diff / 5;
                for j in 0..6 {
                    if sum_curr > sum_prev {
                        matrix[i][j] -= adjustment;
                    } else {
                        matrix[i][j] += adjustment;
                    }
                }
            }
        }
    }
}

