import math

def mathematical_analyzer(data):
    if isinstance(data, dict):
        result = analyze_dict(data)
    elif isinstance(data, list):
        result = analyze_list(data)
    else:
        result = {"value": analyze_single_value(data)}
    return result

def analyze_dict(data):
    result = {"values": {}, "metrics": {}}
    for key, value in sorted(data.items(), key=lambda x: str(x[0]))[:5]:
        key_str = str(key)
        transformed = analyze_single_value(value)
        result["values"][key_str] = transformed
    if result["values"]:
        values = list(result["values"].values())
        result["metrics"]["sum"] = sum(values)
        result["metrics"]["product"] = math.prod(values) % 1000
        sum_value = result["metrics"]["sum"]
        result["metrics"]["prime_factors"] = find_prime_factors(sum_value)
    return result

def analyze_list(data):
    result = {"elements": []}
    for item in data[:10]:
        transformed = analyze_single_value(item)
        result["elements"].append(transformed)
    if result["elements"]:
        elements = result["elements"]
        result["sum"] = sum(elements)
        result["digit_sum"] = sum(digit_sum(e) for e in elements)
        if len(elements) >= 2:
            differences = [elements[i+1] - elements[i] for i in range(len(elements)-1)]
            if all(d == differences[0] for d in differences):
                result["arithmetic"] = True
                result["difference"] = differences[0]
    return result

def analyze_single_value(value):
    if isinstance(value, int):
        return transform_integer(value)
    elif isinstance(value, str):
        return transform_string(value)
    elif isinstance(value, list):
        return sum(analyze_single_value(item) for item in value[:5])
    elif isinstance(value, dict):
        return sum(analyze_single_value(k) + analyze_single_value(v) for k, v in list(value.items())[:5])
    else:
        return 0

def transform_integer(n):
    if n == 0:
        return 0
    abs_n = abs(n)
    result = digit_sum(abs_n) * math.gcd(abs_n, 12)
    return result if n > 0 else -result

def transform_string(s):
    if not s:
        return 0
    total = 0
    for i, char in enumerate(s[:10]):
        char_value = ord(char) - ord('a') + 1 if 'a' <= char <= 'z' else \
                     ord(char) - ord('A') + 1 if 'A' <= char <= 'Z' else \
                     int(char) if char.isdigit() else 0
        total += char_value * (i + 1)
    return total

def digit_sum(n):
    return sum(int(digit) for digit in str(abs(n)))

def find_prime_factors(n):
    if n <= 1:
        return []
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    for i in range(3, min(int(math.sqrt(n)) + 1, 100), 2):
        while n % i == 0:
            factors.append(i)
            n //= i
            if len(factors) >= 5:
                break
    if n > 2:
        factors.append(n)
    return factors[:5]
