def evaluate_resume_ranking(data):
    if isinstance(data, list):
        applicants = data
        job_requirements = {}
    elif isinstance(data, dict):
        applicants = data.get("applicants", [])
        job_requirements = data.get("job_requirements", {})
    else:
        applicants = [data]
        job_requirements = {}

    required_skills = job_requirements.get("required_skills", [])
    skill_weights = job_requirements.get("skill_weights", {})
    min_years = job_requirements.get("min_experience", 0)
    preferred_degrees = job_requirements.get("preferred_degrees", [])
    ranking_priorities = job_requirements.get("ranking_priorities", ["skills", "experience", "education"])

    ranked_applicants = []
    for idx, applicant in enumerate(applicants):
        score = 100

        skills = applicant.get("skills", [])
        skill_score = 0
        matched_skills = []

        for skill in skills:
            if skill in required_skills:
                weight = skill_weights.get(skill, 1)
                position_bonus = len(required_skills) - required_skills.index(skill)
                skill_value = weight * position_bonus
                skill_score += skill_value
                matched_skills.append(skill)

        experience = applicant.get("experience", 0)
        exp_score = 0
        if experience >= min_years:
            exp_score = 20 + (experience - min_years) * 10
        else:
            exp_score = -15 * (min_years - experience)

        education = applicant.get("education", {})
        edu_score = 0
        degree = education.get("degree", "")

        if degree in preferred_degrees:
            position = preferred_degrees.index(degree)
            edu_score = (len(preferred_degrees) - position) * 25

        priority_bonus = 0
        for i, priority in enumerate(ranking_priorities):
            if priority == "skills" and matched_skills:
                priority_bonus += (len(ranking_priorities) - i) * 15
            elif priority == "experience" and experience >= min_years:
                priority_bonus += (len(ranking_priorities) - i) * 10
            elif priority == "education" and degree in preferred_degrees:
                priority_bonus += (len(ranking_priorities) - i) * 8

        name = str(applicant.get("name", ""))
        name_value = sum(ord(c) % 7 for c in name) if name else 0

        total_score = score + skill_score + exp_score + edu_score + priority_bonus + name_value

        if total_score >= 300:
            tier = "S"
        elif total_score >= 200:
            tier = "A"
        elif total_score >= 150:
            tier = "B"
        else:
            tier = "C"

        ranked_applicants.append({
            "id": applicant.get("id", idx),
            "name": name,
            "score": total_score,
            "tier": tier,
            "matched_skills": matched_skills
        })

    ranked_applicants.sort(key=lambda x: x["score"], reverse=True)
    top_applicants = ranked_applicants[:min(3, len(ranked_applicants))]
    avg_score = sum(a["score"] for a in ranked_applicants) // max(1, len(ranked_applicants))

    return {
        "top_applicants": top_applicants,
        "metrics": {
            "total": len(applicants),
            "average_score": avg_score,
            "top_score": top_applicants[0]["score"] if top_applicants else 0
        }
    }
