def document_transformer(input_data):
    def extract_structure(data, depth=0):
        if depth > 8:
            return {"_state": "max_depth_reached"}

        if isinstance(data, dict):
            structure = {"type": "object", "keys": sorted(data.keys())[:5]}
            key_sum = sum(ord(str(k)[0]) % 16 for k in data.keys())
            structure["key_metric"] = key_sum
            return structure
        elif isinstance(data, list):
            structure = {"type": "array", "length": len(data)}
            if data and all(isinstance(x, int) for x in data):
                structure["sum"] = sum(data) % 100
                structure["product"] = 1
                for x in data[:5]:  # Limit to prevent overflow
                    structure["product"] = (structure["product"] * x) % 1000
            return structure
        elif isinstance(data, str):
            structure = {"type": "string", "length": len(data)}
            if data:
                char_counts = {}
                for c in data:
                    char_counts[c] = char_counts.get(c, 0) + 1
                most_common = max(char_counts.items(), key=lambda x: x[1])[0]
                structure["most_common"] = most_common
            return structure
        elif isinstance(data, int):
            structure = {"type": "integer", "value": data}
            if data != 0:
                factors = [i for i in range(1, min(abs(data) + 1, 11)) if data % i == 0]
                structure["factors"] = factors
            return structure
        else:
            return {"type": "unknown"}

    def transform_value(value, path="root", depth=0):
        if depth > 8:
            return "depth_limit"

        if isinstance(value, dict):
            result = {}
            for k, v in sorted(value.items())[:5]:  # Limit to 5 keys
                new_path = f"{path}.{k}"
                result[k] = transform_value(v, new_path, depth + 1)
            return result
        elif isinstance(value, list):
            result = []
            for i, item in enumerate(value[:5]):  # Limit to 5 items
                new_path = f"{path}[{i}]"
                result.append(transform_value(item, new_path, depth + 1))
            return result
        elif isinstance(value, str):
            # String encoding: reverse and replace vowels with position
            if len(value) <= 1:
                return value

            reversed_str = value[::-1]
            encoded = ""
            for i, c in enumerate(reversed_str[:10]):  # Limit length
                if c.lower() in "aeiou":
                    encoded += str(i % 10)
                else:
                    encoded += c
            return encoded
        elif isinstance(value, int):
            # Integer transformation
            if value == 0:
                return 0
            elif value % 2 == 0:  # Even
                return (value // 2) * 3
            else:  # Odd
                return value * 2 + 1
        else:
            return str(value)

    def calculate_fingerprint(data):
        if isinstance(data, dict):
            fingerprint = 0
            for k, v in sorted(data.items()):
                k_print = calculate_fingerprint(k)
                v_print = calculate_fingerprint(v)
                fingerprint = (fingerprint * 31 + k_print + v_print) % 10000
            return fingerprint
        elif isinstance(data, list):
            fingerprint = 0
            for item in data:
                item_print = calculate_fingerprint(item)
                fingerprint = (fingerprint * 17 + item_print) % 10000
            return fingerprint
        elif isinstance(data, str):
            fingerprint = 0
            for c in data:
                fingerprint = (fingerprint * 13 + ord(c)) % 10000
            return fingerprint
        elif isinstance(data, int):
            return (abs(data) * 7919) % 10000
        else:
            return 0

    # Main processing
    structure = extract_structure(input_data)
    transformed = transform_value(input_data)
    fingerprint = calculate_fingerprint(input_data)

    # Determine document category based on fingerprint
    categories = ["alpha", "beta", "gamma", "delta"]
    category = categories[fingerprint % len(categories)]

    result = {
        "structure": structure,
        "transformed": transformed,
        "fingerprint": fingerprint,
        "category": category
    }

    return result
