def deduplicate_crm_contacts(crm_data):
    """Deduplicate CRM contacts using advanced similarity algorithms and clustering techniques."""
    # Input validation with comprehensive error handling
    if not isinstance(crm_data, dict):
        return {"error": "Input must be a dictionary", "contacts": [], "merge_info": {}, "stats": {"original": 0, "final": 0}}

    if "contacts" not in crm_data:
        return {"error": "Input requires 'contacts' key", "contacts": [], "merge_info": {}, "stats": {"original": 0, "final": 0}}

    contacts = crm_data.get("contacts", [])
    if not contacts:
        return {"contacts": [], "merge_info": {}, "stats": {"original": 0, "final": 0, "details": "No contacts provided"}}

    # Extract and enrich settings with sophisticated defaults
    settings = crm_data.get("settings", {})
    threshold = settings.get("threshold", 10)
    weights = settings.get("weights", {
        "name": 3, "email": 5, "phone": 4, "address": 2, "company": 1, "title": 1, "social": 2
    })

    # Advanced string comparison utilities
    class SimilarityMetrics:
        @staticmethod
        def levenshtein_distance(s1, s2):
            if not s1 or not s2:
                return float('inf')
            if s1 == s2:
                return 0

            # Initialize matrix
            rows, cols = len(s1) + 1, len(s2) + 1
            distance_matrix = [[0 for _ in range(cols)] for _ in range(rows)]

            # Populate matrix
            for i in range(1, rows):
                distance_matrix[i][0] = i
            for j in range(1, cols):
                distance_matrix[0][j] = j

            for i in range(1, rows):
                for j in range(1, cols):
                    if s1[i-1] == s2[j-1]:
                        cost = 0
                    else:
                        cost = 1
                    distance_matrix[i][j] = min(
                        distance_matrix[i-1][j] + 1,  # deletion
                        distance_matrix[i][j-1] + 1,  # insertion
                        distance_matrix[i-1][j-1] + cost  # substitution
                    )

                    # Transposition check for adjacent characters
                    if i > 1 and j > 1 and s1[i-1] == s2[j-2] and s1[i-2] == s2[j-1]:
                        distance_matrix[i][j] = min(distance_matrix[i][j], distance_matrix[i-2][j-2] + cost)

            return distance_matrix[rows-1][cols-1]

        @staticmethod
        def normalized_levenshtein(s1, s2):
            if not s1 or not s2:
                return 0.0
            distance = SimilarityMetrics.levenshtein_distance(s1, s2)
            max_len = max(len(s1), len(s2))
            return 1.0 - (distance / max_len if max_len > 0 else 0)

        @staticmethod
        def jaccard_similarity(str1, str2):
            if not str1 or not str2:
                return 0.0

            # Create sets of words and n-grams for better comparison
            set1 = set(str1.lower().split())
            set2 = set(str2.lower().split())

            # Add character bigrams for fuzzy matching
            for s in [str1.lower(), str2.lower()]:
                ngrams = [s[i:i+2] for i in range(len(s)-1)]
                if s == str1.lower():
                    set1.update(ngrams)
                else:
                    set2.update(ngrams)

            intersection = len(set1.intersection(set2))
            union = len(set1.union(set2))

            return intersection / union if union > 0 else 0.0

        @staticmethod
        def normalize_phone(phone):
            if not phone:
                return ""
            # Extract only digits, handle international format
            normalized = ''.join(c for c in phone if c.isdigit())
            # Strip leading 1 for North American numbers
            if len(normalized) > 10 and normalized.startswith('1'):
                normalized = normalized[1:]
            return normalized

    # Advanced disjoint-set data structure for contact clustering
    class DisjointSet:
        def __init__(self, size):
            self.parent = list(range(size))
            self.rank = [0] * size
            self.size = [1] * size  # Track size of each set

        def find(self, x):
            # Path compression find
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])
            return self.parent[x]

        def union(self, x, y):
            root_x = self.find(x)
            root_y = self.find(y)

            if root_x == root_y:
                return False

            # Union by rank with size tracking
            if self.rank[root_x] < self.rank[root_y]:
                self.parent[root_x] = root_y
                self.size[root_y] += self.size[root_x]
            elif self.rank[root_x] > self.rank[root_y]:
                self.parent[root_y] = root_x
                self.size[root_x] += self.size[root_y]
            else:
                self.parent[root_y] = root_x
                self.rank[root_x] += 1
                self.size[root_x] += self.size[root_y]
            return True

        def get_sets(self):
            # Extract all disjoint sets as clusters
            clusters = {}
            for i in range(len(self.parent)):
                root = self.find(i)
                if root not in clusters:
                    clusters[root] = []
                clusters[root].append(i)
            return clusters

    # Contact similarity calculation with multi-dimensional scoring
    similarity_graph = {}
    field_similarity_details = {}

    for i in range(len(contacts)):
        for j in range(i+1, len(contacts)):
            c1, c2 = contacts[i], contacts[j]
            composite_score = 0
            field_scores = {}

            # Sophisticated name comparison
            if "name" in c1 and "name" in c2:
                name_parts_score = 0
                name_parts_count = 0

                for part in ["first", "middle", "last"]:
                    n1 = c1["name"].get(part, "").lower().strip()
                    n2 = c2["name"].get(part, "").lower().strip()

                    if n1 and n2:
                        name_parts_count += 1
                        if n1 == n2:  # Exact match
                            name_parts_score += 1
                        elif n1 in n2 or n2 in n1:  # Substring match
                            name_parts_score += 0.8
                        else:  # Fuzzy matching for names with typos
                            similarity = SimilarityMetrics.normalized_levenshtein(n1, n2)
                            if similarity > 0.7:  # High similarity threshold
                                name_parts_score += similarity

                if name_parts_count > 0:
                    name_score = (name_parts_score / name_parts_count) * weights["name"] * 2
                    composite_score += name_score
                    field_scores["name"] = round(name_score, 2)

            # Email comparison with domain and local-part analysis
            email1 = c1.get("email", "").lower().strip()
            email2 = c2.get("email", "").lower().strip()

            if email1 and email2:
                if email1 == email2:  # Exact match
                    email_score = weights["email"]
                    composite_score += email_score
                    field_scores["email"] = email_score
                else:
                    # Analyze email components
                    email1_parts = email1.split('@')
                    email2_parts = email2.split('@')

                    if len(email1_parts) == 2 and len(email2_parts) == 2:
                        # Domain comparison
                        if email1_parts[1] == email2_parts[1]:
                            domain_score = weights["email"] * 0.4
                            composite_score += domain_score
                            field_scores["email_domain"] = domain_score

                        # Username normalization and comparison
                        username1 = email1_parts[0].replace('.', '').split('+')[0]
                        username2 = email2_parts[0].replace('.', '').split('+')[0]

                        if username1 == username2:
                            username_score = weights["email"] * 0.5
                            composite_score += username_score
                            field_scores["email_username"] = username_score
                        elif SimilarityMetrics.normalized_levenshtein(username1, username2) > 0.8:
                            username_score = weights["email"] * 0.3
                            composite_score += username_score
                            field_scores["email_username_similar"] = username_score

            # Advanced phone comparison
            phone1 = SimilarityMetrics.normalize_phone(c1.get("phone", ""))
            phone2 = SimilarityMetrics.normalize_phone(c2.get("phone", ""))

            if phone1 and phone2:
                if phone1 == phone2:  # Exact match
                    phone_score = weights["phone"]
                    composite_score += phone_score
                    field_scores["phone"] = phone_score
                elif len(phone1) >= 7 and len(phone2) >= 7:
                    # Last 7 digits match (different area codes)
                    if phone1[-7:] == phone2[-7:]:
                        phone_score = weights["phone"] * 0.8
                        composite_score += phone_score
                        field_scores["phone_partial"] = phone_score
                    # Last 4 digits match
                    elif phone1[-4:] == phone2[-4:]:
                        phone_score = weights["phone"] * 0.4
                        composite_score += phone_score
                        field_scores["phone_last4"] = phone_score

            # Sophisticated address comparison
            addr1 = c1.get("address", "").lower().strip()
            addr2 = c2.get("address", "").lower().strip()

            if addr1 and addr2:
                if addr1 == addr2:  # Exact match
                    addr_score = weights["address"]
                    composite_score += addr_score
                    field_scores["address"] = addr_score
                else:
                    # Smart address comparison using Jaccard similarity
                    jaccard_score = SimilarityMetrics.jaccard_similarity(addr1, addr2)
                    if jaccard_score > 0.6:  # Significant overlap
                        addr_score = weights["address"] * jaccard_score
                        composite_score += addr_score
                        field_scores["address_similarity"] = round(addr_score, 2)

            # Company name comparison
            company1 = c1.get("company", "").lower().strip()
            company2 = c2.get("company", "").lower().strip()

            if company1 and company2:
                if company1 == company2:  # Exact match
                    company_score = weights["company"]
                    composite_score += company_score
                    field_scores["company"] = company_score
                else:
                    # Handle company name variations
                    # Remove common suffixes
                    for suffix in [" inc", " llc", " ltd", " co", " corporation", " corp"]:
                        company1 = company1.replace(suffix, "")
                        company2 = company2.replace(suffix, "")

                    company_similarity = SimilarityMetrics.normalized_levenshtein(company1, company2)
                    if company_similarity > 0.8:  # Very similar
                        company_score = weights["company"] * company_similarity
                        composite_score += company_score
                        field_scores["company_similarity"] = round(company_score, 2)

            # Social media handles (for added complexity)
            social1 = c1.get("social", {})
            social2 = c2.get("social", {})

            if social1 and social2:
                social_score = 0
                for platform in set(social1.keys()).intersection(set(social2.keys())):
                    if social1[platform] == social2[platform]:
                        social_score += weights.get("social", 1) / len(set(social1.keys()).union(set(social2.keys())))

                if social_score > 0:
                    composite_score += social_score
                    field_scores["social"] = round(social_score, 2)

            # Store significant similarities for clustering
            if composite_score >= threshold:
                similarity_graph[(i, j)] = composite_score
                field_similarity_details[(i, j)] = field_scores

    # Hierarchical clustering with the disjoint-set data structure
