        # Advanced master record selection using weighted scoring
        contact_quality_scores = []
        for idx in cluster:
            contact = contacts[idx]
            # Calculate data quality score based on completeness and freshness
            quality_score = sum(2 for k in contact if contact[k])

            # Boost score for critical fields
            if "email" in contact and contact["email"]:
                quality_score += 3
            if "phone" in contact and contact["phone"]:
                quality_score += 2
            if "name" in contact and any(contact["name"].values()):
                quality_score += 3

            # Consider record freshness if available
            if "last_updated" in contact:
                quality_score += 1

            contact_quality_scores.append((idx, quality_score))

        # Select master record - highest quality score
        master_idx, _ = max(contact_quality_scores, key=lambda x: x[1])
        merged_record = dict(contacts[master_idx])

        # Initialize merge tracking
        merge_info[str(master_idx)] = {
            "merged_with": [i for i in cluster if i != master_idx],
            "updated_fields": {},
            "field_sources": {},
            "confidence_scores": {}
        }

        # Field-level merging with intelligent conflict resolution
        for field in set(k for c in cluster for k in contacts[c].keys()):
            if field == "name":  # Special handling for nested name field
                if "name" not in merged_record:
                    # Find best name record
                    for idx in cluster:
                        if idx != master_idx and "name" in contacts[idx]:
                            merged_record["name"] = dict(contacts[idx]["name"])
                            merge_info[str(master_idx)]["field_sources"]["name"] = idx
                            merge_stats["fields_merged"]["name"] += 1
                            break
                else:
                    # Merge name components
                    for idx in cluster:
                        if idx == master_idx or "name" not in contacts[idx]:
                            continue

                        other_name = contacts[idx]["name"]
                        for part in ["first", "middle", "last", "prefix", "suffix"]:
                            if part not in merged_record["name"] or not merged_record["name"].get(part):
                                if part in other_name and other_name.get(part):
                                    merged_record["name"][part] = other_name[part]
                                    merge_info[str(master_idx)]["updated_fields"][f"name.{part}"] = other_name[part]
                                    merge_info[str(master_idx)]["field_sources"][f"name.{part}"] = idx
                                    merge_stats["fields_merged"]["name"] += 1
            else:  # Handle other fields
                field_values = [(idx, contacts[idx].get(field)) for idx in cluster 
                               if field in contacts[idx] and contacts[idx].get(field)]

                if not field_values:
                    continue

                if field not in merged_record or not merged_record.get(field):
                    # Take the most common value or first if tied
                    value_counts = {}
                    for _, val in field_values:
                        if isinstance(val, (dict, list)):
                            val_str = str(val)  # Convert complex types to string for counting
                        else:
                            val_str = val
                        value_counts[val_str] = value_counts.get(val_str, 0) + 1

                    most_common = max(value_counts.items(), key=lambda x: x[1])
                    best_value = next(val for _, val in field_values if str(val) == most_common[0])
                    best_idx = next(idx for idx, val in field_values if str(val) == most_common[0])

                    merged_record[field] = best_value
                    merge_info[str(master_idx)]["updated_fields"][field] = best_value
                    merge_info[str(master_idx)]["field_sources"][field] = best_idx
                    merge_stats["fields_merged"][field if field in merge_stats["fields_merged"] else "other"] += 1

                # Store alternative values
                alt_values = [val for _, val in field_values 
                             if str(val) != str(merged_record.get(field))]
                if alt_values:
                    if "alternative_values" not in merged_record:
                        merged_record["alternative_values"] = {}
                    merged_record["alternative_values"][field] = alt_values

        # Calculate confidence scores for merged record
        for field in merged_record:
            if field == "alternative_values" or field == "merge_metadata":
                continue

            # Count how many contacts in cluster have same value
            if field == "name" and isinstance(merged_record[field], dict):
                # For composite name field
                confidence = {}
                for part in merged_record["name"]:
                    matching = sum(1 for idx in cluster 
                                 if "name" in contacts[idx] and 
                                 part in contacts[idx]["name"] and 
                                 contacts[idx]["name"].get(part) == merged_record["name"].get(part))
                    confidence[part] = round(matching / len(cluster), 2)
                merge_info[str(master_idx)]["confidence_scores"]["name"] = confidence
            else:
                # For other fields
                matching = sum(1 for idx in cluster 
                             if field in contacts[idx] and 
                             str(contacts[idx].get(field)) == str(merged_record.get(field)))
                merge_info[str(master_idx)]["confidence_scores"][field] = round(matching / len(cluster), 2)

        # Add merge metadata
        merged_record["merge_metadata"] = {
            "master_record": master_idx,
            "merged_from": cluster,
            "merged_at": "__TIMESTAMP__"  # Placeholder for timestamp
        }

        merged_contacts.append(merged_record)

    # Enriched statistics about the deduplication process
    stats = {
        "original": len(contacts),
        "final": len(merged_contacts),
        "reduction": len(contacts) - len(merged_contacts),
        "reduction_percentage": round((len(contacts) - len(merged_contacts)) / len(contacts) * 100, 2) if contacts else 0,
        "clusters": {
            "total": len(clusters),
            "distribution": merge_stats["cluster_sizes"],
            "largest_size": max(merge_stats["cluster_sizes"].keys()) if merge_stats["cluster_sizes"] else 0
        },
        "merged_fields": merge_stats["fields_merged"],
        "similarity_threshold": threshold,
        "similarity_metrics_used": ["levenshtein", "jaccard", "normalized_comparison"],
        "processing_stats": {
            "comparisons_performed": len(contacts) * (len(contacts) - 1) // 2,
            "similarity_matches": len(similarity_graph)
        }
    }

    return {
        "contacts": merged_contacts,
        "merge_info": merge_info,
        "stats": stats
    }
