    use std::io::{self, Read};

    fn network_topology_analyzer(input: Value) -> Value {
    let mut nodes = Vec::new();
    let mut connections = Vec::new();

    // Parse input data
    if let Value::Object(topology) = &input {
        if let Some(Value::Array(node_array)) = topology.get("nodes") {
            for node in node_array {
                if let Value::Object(_) = node {
                    nodes.push(node.clone());
                }
            }
        }

        if let Some(Value::Array(conn_array)) = topology.get("connections") {
            for conn in conn_array {
                if let Value::Object(_) = conn {
                    connections.push(conn.clone());
                }
            }
        }
    }

    if nodes.is_empty() || connections.is_empty() {
        return json!({"error": "Invalid topology format"});
    }

    // Calculate node connectivity matrix
    let mut connectivity = vec![vec![0i64; nodes.len()]; nodes.len()];

    for connection in &connections {
        if let Value::Object(conn) = connection {
            let source = if let Some(Value::Number(s)) = conn.get("source") {
                s.as_u64().unwrap_or(0) as usize
            } else { 0 };

            let target = if let Some(Value::Number(t)) = conn.get("target") {
                t.as_u64().unwrap_or(0) as usize
            } else { 0 };

            let weight = if let Some(Value::Number(w)) = conn.get("weight") {
                w.as_i64().unwrap_or(1)
            } else { 1 };

            if source < nodes.len() && target < nodes.len() {
                connectivity[source][target] = weight;
                connectivity[target][source] = weight; // Assuming undirected graph
            }
        }
    }

    // Calculate node resilience scores using a complex algorithm
    let mut node_scores = Vec::new();

    for (idx, node) in nodes.iter().enumerate() {
        if let Value::Object(node_obj) = node {
            let capacity = if let Some(Value::Number(c)) = node_obj.get("capacity") {
                c.as_i64().unwrap_or(1)
            } else { 1 };

            let reliability = if let Some(Value::Number(r)) = node_obj.get("reliability") {
                r.as_i64().unwrap_or(5)
            } else { 5 };

            // Calculate direct connections
            let connections_count: i64 = connectivity[idx].iter().map(|&w| if w > 0 { 1 } else { 0 }).sum();

            // Calculate weighted importance
            let mut importance = 0i64;
            for (j, &weight) in connectivity[idx].iter().enumerate() {
                if weight > 0 {
                    // Sum of this node's connections to its neighbors' connections
                    let neighbor_connections: i64 = connectivity[j].iter().map(|&w| if w > 0 { 1 } else { 0 }).sum();
                    importance += weight * neighbor_connections;
                }
            }

            // Calculate path diversity (number of different paths to other nodes)
            let mut path_diversity = 0i64;
            for j in 0..nodes.len() {
                if j != idx {
                    let direct = connectivity[idx][j];
                    let mut indirect = 0i64;
                    for k in 0..nodes.len() {
                        if k != idx && k != j {
                            if connectivity[idx][k] > 0 && connectivity[k][j] > 0 {
                                indirect += 1;
                            }
                        }
                    }
                    path_diversity += direct + (indirect / 2);
                }
            }

            // Final complex resilience formula
            let resilience = (capacity * 3) + (reliability * 2) + 
                             (connections_count * 5) + (importance / 2) + 
                             (path_diversity * 4);

            let normalized_resilience = resilience % 100; // Keep scores manageable

            let tier = match normalized_resilience {
                0..=20 => 1,
                21..=40 => 2,
                41..=60 => 3,
                61..=80 => 4,
                _ => 5
            };

            node_scores.push((idx, normalized_resilience, tier));
        }
    }

    // Reorder nodes by resilience score with special ordering within tiers
    node_scores.sort_by(|a, b| {
        if a.2 != b.2 {
            b.2.cmp(&a.2) // Higher tier first
        } else {
            // Within same tier, use a complex ordering
            let a_factor = (a.1 * 7) % 13;
            let b_factor = (b.1 * 7) % 13;
            a_factor.cmp(&b_factor)
        }
    });

    // Generate optimized network topology
    let mut optimized_nodes = Vec::new();
    let mut optimized_connections = Vec::new();
    let mut new_indices = vec![0usize; nodes.len()];

    for (new_idx, (old_idx, score, tier)) in node_scores.iter().enumerate() {
        if let Some(Value::Object(node)) = nodes.get(*old_idx) {
            let mut optimized_node = node.clone();

            // Add analysis metadata
            optimized_node.insert("resilience_score".to_string(), 
                              Value::Number(serde_json::Number::from(*score)));
            optimized_node.insert("tier".to_string(), 
                              Value::Number(serde_json::Number::from(*tier)));

            // Store new index mapping
            new_indices[*old_idx] = new_idx;

            optimized_nodes.push(Value::Object(optimized_node));
        }
    }

    // Remap connections to use new node indices
    for connection in connections {
        if let Value::Object(conn) = connection {
            let source = if let Some(Value::Number(s)) = conn.get("source") {
                s.as_u64().unwrap_or(0) as usize
            } else { 0 };

            let target = if let Some(Value::Number(t)) = conn.get("target") {
                t.as_u64().unwrap_or(0) as usize
            } else { 0 };

            if source < nodes.len() && target < nodes.len() {
                let mut optimized_conn = conn.clone();
                optimized_conn.insert("source".to_string(), 
                                 Value::Number(serde_json::Number::from(new_indices[source] as u64)));
                optimized_conn.insert("target".to_string(), 
                                 Value::Number(serde_json::Number::from(new_indices[target] as u64)));

                // Calculate new connection properties based on node resilience
                let source_score = node_scores.iter().find(|(idx, _, _)| *idx == source).map(|(_, s, _)| s).unwrap_or(&0);
                let target_score = node_scores.iter().find(|(idx, _, _)| *idx == target).map(|(_, s, _)| s).unwrap_or(&0);

                let efficiency = ((source_score + target_score) / 3) % 10;
                optimized_conn.insert("efficiency".to_string(), 
                                 Value::Number(serde_json::Number::from(efficiency)));

                optimized_connections.push(Value::Object(optimized_conn));
            }
        }
    }

    // Final result
    json!({
        "nodes": optimized_nodes,
        "connections": optimized_connections,
        "network_resilience": node_scores.iter().map(|(_, score, _)| score).sum::<i64>() % 1000
    })
}

    fn main() {
        let mut buf = String::new();
        io::stdin().read_to_string(&mut buf).unwrap();
        let inp: Value = from_str(&buf).unwrap();
        let out = network_topology_analyzer(inp);
        println!("{}", to_string(&out).unwrap());
    }

