    fn document_security_processor(input: serde_json::Value) -> serde_json::Value {
    use serde_json::{json, Map, Value};

    // Extract components
    let keys = if let Value::Array(k) = &input["keys"] {
        k.clone()
    } else {
        return json!({"error": "Missing keys array"});
    };

    let text = if let Value::String(t) = &input["text"] {
