    };

    // Step 1: Calculate text's base value
    let mut base_value = 0;
    for (i, ch) in text.chars().enumerate() {
        let char_code = ch as i32;
        let position_factor = (i as i32 % 7) + 1;
        base_value = (base_value + char_code * position_factor) % 10000;
    }

    // Step 2: Apply transformation using keys
    let mut transformed_value = base_value;

    for (i, key) in keys.iter().enumerate().take(16) {  // Limit to 16 keys
        match key {
            Value::Number(n) => {
                if let Some(num) = n.as_i64() {
                    let key_value = num as i32;
                    let operation = i % 4;

                    match operation {
                        0 => transformed_value = (transformed_value + key_value) % 10000,
                        1 => transformed_value = (transformed_value * (key_value % 100 + 1)) % 10000,
                        2 => transformed_value = (transformed_value - key_value + 10000) % 10000,
                        _ => transformed_value = (transformed_value ^ (key_value % 100)) % 10000,
                    }
                }
            },
            Value::String(s) => {
                let key_chars: Vec<char> = s.chars().collect();
                for (j, &ch) in key_chars.iter().enumerate().take(8) {  // Limit to 8 chars
                    let char_code = ch as i32;
                    let operation = (i + j) % 4;

                    match operation {
                        0 => transformed_value = (transformed_value + char_code) % 10000,
                        1 => transformed_value = (transformed_value * ((char_code % 10) + 1)) % 10000,
                        2 => transformed_value = (transformed_value - char_code + 10000) % 10000,
                        _ => transformed_value = (transformed_value ^ (char_code % 100)) % 10000,
                    }
                }
            },
            _ => {}
        }
    }

    // Step 3: Process with matrix
    let mut matrix_values = Vec::new();

    for row in matrix.iter().take(8) {  // Limit to 8 rows
        if let Value::Array(r) = row {
            let mut row_values = Vec::new();
            for cell in r.iter().take(8) {  // Limit to 8 columns
                if let Value::Number(n) = cell {
                    if let Some(val) = n.as_i64() {
                        row_values.push(val as i32);
                    } else {
                        row_values.push(0);
                    }
                } else {
                    row_values.push(0);
                }
            }
            matrix_values.push(row_values);
        }
    }

    // Calculate matrix effect
    let mut security_codes = Vec::new();

    for i in 0..matrix_values.len() {
        let row = &matrix_values[i];
        let mut code = 0;

        for j in 0..row.len() {
            let cell = row[j];
            let digit = (transformed_value / (10_i32.pow(j as u32 % 4))) % 10;

            code = (code + cell * digit) % 10000;
        }

        security_codes.push(code);
    }

    // Step 4: Generate verification signature
    let verification_base = security_codes.iter().fold(0, |acc, &x| (acc + x) % 10000);

    let mut signature_components = Vec::new();
    let mut temp = verification_base;

    for _ in 0..4 {
        signature_components.push(temp % 100);
        temp /= 100;
    }

    let security_signature = signature_components.iter().fold(1, |acc, &part| (acc * (part + 1)) % 10000);

    // Create the result
    let mut result = Map::new();
    result.insert("base_value".to_string(), json!(base_value));
    result.insert("transformed_value".to_string(), json!(transformed_value));
    result.insert("security_codes".to_string(), json!(security_codes));
    result.insert("verification_base".to_string(), json!(verification_base));
    result.insert("security_signature".to_string(), json!(security_signature));
    result.insert("valid".to_string(), json!(security_signature > 5000));

