'use strict'
import {compareTwoStrings} from 'string-similarity'
import Fraction from 'fraction.js'
export function transformComplex(cfg){
  const {names = [], data = [], queries = []} = cfg
  const counts = new Map()
  const sums = new Proxy({}, {
    get(target, prop) {
      if (!Reflect.has(target, prop)) {
        const idx = names.indexOf(prop)
        const len = data[idx]?.length || 0
        target[prop] = Array.from({ length: len }, () => new Fraction(0))
      }
      return Reflect.get(target, prop)
    }
  })

  const matches = {}
  queries.forEach(query => {
    let best = names[0] || '', bestScore = -Infinity
    names.forEach(name => {
      const score = Math.pow(compareTwoStrings(query, name), 1)
      if (score > bestScore) {
        bestScore = score
        best = name
      }
    })
    matches[query] = best
    counts.set(best, (counts.get(best) || 0) + 1)

    const row = data[names.indexOf(best)] || []
    row.forEach((val, i) => {
      sums[best][i] = sums[best][i].add(new Fraction(val))
    })
  })

  const groups = names.reduce((acc, name) => {
    const cnt = counts.get(name) || 1
    acc[name] = sums[name].map(fr => fr.div(cnt).valueOf())
    return acc
  }, {})

  return { matches, groups }
}
