def data_pipeline_processor(input_data):
    def transform_element(element, level=0, path=""):
        if isinstance(element, dict):
            result = {}
            keys = sorted(element.keys())
            for i, key in enumerate(keys):
                new_path = f"{path}.{key}" if path else key
                value = element[key]

                # Apply transformations based on key position and level
                if i % 3 == 0:
                    result[key] = transform_element(value, level + 1, new_path)
                elif i % 3 == 1:
                    if isinstance(value, (int, str)):
                        result[key] = str(value) + "_" + str(level)
                    else:
                        result[key] = transform_element(value, level + 2, new_path)
                else:
                    if isinstance(value, (list, tuple)):
                        result[key] = [level + len(str(x)) for x in value if isinstance(x, (int, str))][:5]
                    else:
                        result[key] = transform_element(value, level + 3, new_path)
            return result

        elif isinstance(element, list):
            if not element:
                return [level]

            result = []
            for i, item in enumerate(element[:5]):
                if i % 2 == 0:
                    result.append(transform_element(item, level + i, path + f"[{i}]"))
                else:
                    if isinstance(item, (int, str)):
                        result.append(len(str(item)) * (level + 1))
                    else:
                        result.append(transform_element(item, level + i + 1, path + f"[{i}]"))
            return result

        elif isinstance(element, str):
            if len(element) <= 3:
                return element * (level + 1)
            else:
                chars = [ord(c) % (26 + level) + 97 for c in element.lower()]
                return ''.join([chr(c) for c in chars])[:10]

        elif isinstance(element, int):
            if element % 2 == 0:
                return element * (level + 1) + sum(range(level + 1))
            else:
                return (element + level) ** 2 - level

        else:
            return level * 10

    transformed = transform_element(input_data)

    def extract_metadata(data, depth=0):
        if depth >= 3:
            return {"depth_limit": True}

        if isinstance(data, dict):
            keys_count = len(data)
            value_types = {}
            for k, v in data.items():
                type_name = type(v).__name__
                value_types[type_name] = value_types.get(type_name, 0) + 1

            result = {
                "type": "dict",
                "keys_count": keys_count,
                "value_types": value_types
            }

            if keys_count <= 3:  # Only analyze children for smaller dicts
                result["children"] = {k: extract_metadata(v, depth + 1) for k, v in data.items()}

            return result

        elif isinstance(data, list):
            result = {
                "type": "list",
                "length": len(data)
            }

            if len(data) <= 3:  # Only analyze children for smaller lists
                result["items"] = [extract_metadata(item, depth + 1) for item in data]

            return result

        elif isinstance(data, str):
            return {
                "type": "string",
                "length": len(data)
            }

        elif isinstance(data, int):
            return {
                "type": "integer",
                "value": data,
                "is_even": data % 2 == 0
            }

        else:
            return {"type": "other"}

    metadata = extract_metadata(transformed)

    return {
        "result": transformed,
        "metadata": metadata
    }
