import more_itertools as mit
from collections import Counter

def document_analyzer(input_data):
    # Handle different input types
    if isinstance(input_data, dict):
        text = input_data.get('text', '')
        metadata = input_data.get('metadata', {})
        tags = input_data.get('tags', [])
    elif isinstance(input_data, list):
        text = ' '.join(str(item) for item in input_data)
        metadata = {'length': len(input_data)}
        tags = [str(i) for i in range(len(input_data))]
    else:
        text = str(input_data)
        metadata = {'type': str(type(input_data).__name__)}
        tags = []

    # Text processing
    words = text.split() if isinstance(text, str) else [str(text)]
    chars = list(text) if isinstance(text, str) else []

    # Apply transformations using more_itertools
    word_pairs = list(mit.pairwise(words))[:5] if len(words) > 1 else []
    unique_words = list(mit.unique_everseen(words))[:10]
    word_runs = list(mit.run_length.encode(words))[:5]

    # Calculate word frequency distribution
    word_freq = dict(Counter(words).most_common(5))

    # Create palindrome detector
    def is_palindrome(word):
        chars = list(str(word).lower())
        return chars == list(reversed(chars))

    palindromes = [w for w in unique_words if is_palindrome(w)]

    # Process tags using transformations
    processed_tags = []
    for idx, tag in enumerate(tags[:5]):
        tag_str = str(tag)
        tag_data = {
            'original': tag_str,
            'position': idx,
            'reversed': tag_str[::-1],
            'length': len(tag_str)
        }
        if len(tag_str) > 1:
            interspersed = list(mit.intersperse('_', tag_str))
            tag_data['interspersed'] = ''.join(interspersed)
        processed_tags.append(tag_data)

    # Process metadata recursively
    def transform_metadata(value, depth=0):
        if depth > 2 or value is None:
            return value
        if isinstance(value, dict):
            return {k: transform_metadata(v, depth+1) for k, v in list(value.items())[:3]}
        elif isinstance(value, list):
            return [transform_metadata(v, depth+1) for v in value[:3]]
        elif isinstance(value, str):
            if len(value) > 0:
                return ''.join(mit.take(len(value), mit.cycle(value[::-1])))
            return value
        elif isinstance(value, int):
            binary = bin(abs(value))[2:]
            reversed_binary = binary[::-1]
            return int(reversed_binary, 2) * (-1 if value < 0 else 1)
        return value

    transformed_metadata = transform_metadata(metadata)

    # Calculate complexity score
    complexity_score = sum((i+1) * len(w) for i, w in enumerate(words[:15]))

    # Construct result
    result = {
        'statistics': {
            'word_count': len(words),
            'unique_count': len(unique_words),
            'avg_word_length': sum(len(w) for w in words) // max(1, len(words))
        },
        'analysis': {
            'pairs': word_pairs,
            'runs': word_runs,
            'frequency': word_freq,
            'palindromes': palindromes,
            'complexity': complexity_score
        },
        'processed_tags': processed_tags,
        'transformed_metadata': transformed_metadata
    }

    return result
