        conflicts = []
        for day, wins in days.items():
            sorted_w = sorted(wins, key=lambda x: x.start_time)
            for prev, curr in zip(sorted_w, sorted_w[1:]):
                if curr.start_time < prev.end_time:
                    conflicts.append(f"{day}: {prev.start_time}-{prev.end_time} overlaps {curr.start_time}-{curr.end_time}")
