def transform_document(document):
    def process_element(element, path=None, depth=0):
        if path is None:
            path = []

        # Calculate path signature for transformations
        path_signature = sum(ord(str(p)[0]) for p in path) % 26 if path else 0

        if isinstance(element, dict):
            result = {}
            for key in sorted(element.keys()):
                result[key] = process_element(element[key], path + [key], depth + 1)
            return result

        elif isinstance(element, list):
            result = [process_element(item, path + [i], depth + 1) for i, item in enumerate(element)]

            # Special transformation for lists of integers
            if result and all(isinstance(x, int) for x in result):
                return [(x * (i + 1) + depth) % 1000 for i, x in enumerate(result)]
            return result

        elif isinstance(element, str):
            if not element:
                return ""

            # Apply position-dependent character substitution
            result = ""
            for i, char in enumerate(element):
                if char.isalpha():
                    base = ord('a') if char.islower() else ord('A')
                    shift = (path_signature + i + depth) % 26
                    result += chr((ord(char) - base + shift) % 26 + base)
                else:
                    result += char
            return result

        elif isinstance(element, int):
            # Transform integers based on depth and path
            transform_factor = (depth + 1) * 7 + path_signature
            return (element * transform_factor) % 1000

        else:
            return element

    # Process the document
    transformed = process_element(document)

    # Extract structural metadata
    def extract_structure(item, max_depth=3, current_depth=0):
        if current_depth >= max_depth:
            return {"type": "truncated"}

        if isinstance(item, dict):
            keys = sorted(item.keys())[:5]  # Limit to first 5 keys
            return {
                "type": "dict",
                "size": len(item),
                "keys": keys,
                "samples": {k: extract_structure(item[k], max_depth, current_depth + 1) 
                           for k in keys[:3]}  # Sample first 3 keys
            }
        elif isinstance(item, list):
            return {
                "type": "list",
                "length": len(item),
                "samples": [extract_structure(x, max_depth, current_depth + 1) 
                           for x in item[:3]]  # Sample first 3 items
            }
        elif isinstance(item, str):
            return {
                "type": "string",
                "length": len(item)
            }
        elif isinstance(item, int):
            return {
                "type": "integer",
                "value": item
            }
        else:
            return {"type": str(type(item).__name__)}

    # Calculate document complexity
    def calculate_complexity(obj):
        if isinstance(obj, dict):
            return len(obj) + sum(calculate_complexity(v) for v in obj.values())
        elif isinstance(obj, list):
            return len(obj) + sum(calculate_complexity(item) for item in obj)
        else:
            return 1

    return {
        "transformed": transformed,
        "structure": extract_structure(document),
        "complexity": calculate_complexity(document)
    }
