{'flights': [{'id': 'F1', 'arrival': 0, 'departure': 10, 'size': 2, 'preferences': ['G1']}, {'id': 'F2', 'arrival': 5, 'departure': 15, 'size': 3, 'preferences': ['G2']}], 'gates': [{'id': 'G1', 'capacity': 2}, {'id': 'G2', 'capacity': 3}]}

