```js
import _ from 'lodash';

export function planGates(input) {
  const flights = input.flights;
  const gates = input.gates;
  const n = flights.length;
  const m = gates.length;

  // Precompute conflict matrix between flights
  const conflict = Array.from({ length: n }, () => Array(n).fill(false));
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const f1 = flights[i], f2 = flights[j];
      if (!(f1.departure <= f2.arrival || f2.departure <= f1.arrival)) {
        conflict[i][j] = conflict[j][i] = true;
      }
    }
  }

  // Cost matrix: mismatch + preference penalty
  const costMat = flights.map(f => gates.map(g => {
    const prefPenalty = (f.preferences || []).includes(g.id) ? 0 : 5;
    return Math.abs(f.size - g.capacity) + prefPenalty;
  }));

  // Greedy initial assignment
  const assign = Array(n).fill(-1);
  const gateSched = Array.from({ length: m }, () => []);
  for (let i = 0; i < n; i++) {
    let bestCost = Infinity, bestG = 0;
    for (let j = 0; j < m; j++) {
      if (gateSched[j].every(k => !conflict[i][k])) {
        const c = costMat[i][j];
        if (c < bestCost) { bestCost = c; bestG = j; }
      }
    }
    assign[i] = bestG;
    gateSched[bestG].push(i);
  }

  // Score function
  const score = arr => arr.reduce((sum, g, idx) => sum + costMat[idx][g], 0);
  let current = assign.slice();
  let currentCost = score(current);
  let bestAssign = current.slice();
  let bestCost = currentCost;

  // Simulated annealing parameters
  const MAX_ITER = 5000;
  const T0 = 100;

  for (let iter = 0; iter < MAX_ITER; iter++) {
    const T = T0 * (1 - iter / MAX_ITER);
    const cand = current.slice();

    if (Math.random() < 0.6) {
      // Move one flight to a random gate
      const i = _.random(0, n - 1);
      const gj = _.random(0, m - 1);
      const gi = cand[i];
      if (gi !== gj) {
        // Tentative schedules
        const tempSched = gateSched.map(arr => arr.slice());
        tempSched[gi] = tempSched[gi].filter(x => x !== i);
        if (tempSched[gj].every(k => !conflict[i][k])) {
          tempSched[gj].push(i);
          cand[i] = gj;
          const newCost = score(cand);
          const dE = newCost - currentCost;
          if (dE < 0 || Math.random() < Math.exp(-dE / T)) {
            current = cand.slice();
            currentCost = newCost;
            for (let g = 0; g < m; g++) gateSched[g] = tempSched[g];
            if (currentCost < bestCost) {
              bestCost = currentCost;
              bestAssign = current.slice();
            }
          }
        }
      }
    } else {
      // Swap two flights
      const i = _.random(0, n - 1);
      const j = _.random(0, n - 1);
      if (i !== j && current[i] !== current[j]) {
        const gi = current[i], gj = current[j];
        const tempSched = gateSched.map(arr => arr.slice());
        tempSched[gi] = tempSched[gi].filter(x => x !== i);
        tempSched[gj] = tempSched[gj].filter(x => x !== j);
        if (tempSched[gi].every(k => !conflict[j][k]) && tempSched[gj].every(k => !conflict[i][k])) {
          const cand2 = current.slice();
          cand2[i] = gj;
          cand2[j] = gi;
          tempSched[gi].push(j);
          tempSched[gj].push(i);
          const newCost = score(cand2);
          const dE = newCost - currentCost;
          if (dE < 0 || Math.random() < Math.exp(-dE / T)) {
            current = cand2;
            currentCost = newCost;
            for (let g = 0; g < m; g++) gateSched[g] = tempSched[g];
            if (currentCost < bestCost) {
              bestCost = currentCost;
              bestAssign = current.slice();
            }
          }
        }
      }
    }
  }

  // Build output
  const assignments = bestAssign.map((g, idx) => ({
    flightId: flights[idx].id,
    gateId: gates[g].id
  }));

  return { assignments, totalCost: bestCost };
}
