    type: ElementType
    order: conint(strict=True, ge=1)
    node_indices: List[conint(strict=True, gt=0)]

    @model_validator(mode='after')
    def check_node_count(cls, el):
        if el.type == ElementType.triangle:
            expected = (el.order + 1) * (el.order + 2) // 2
        elif el.type == ElementType.quadrilateral:
            expected = (el.order + 1) ** 2
        elif el.type == ElementType.tetrahedron:
            expected = math.comb(el.order + 3, 3)
        elif el.type == ElementType.hexahedron:
            expected = (el.order + 1) ** 3
        else:
            expected = None
        if expected is not None and len(el.node_indices) != expected:
            raise ValueError(f'{el.type} of order {el.order} expects {expected} nodes, got {len(el.node_indices)}')
        return el

class Meta(BaseModel):
    description: str
    version: str
    created_at: datetime
    updated_at: datetime | None = None

class FEMeshSpec(BaseModel):
    nodes: List[Node]
    elements: List[Element]
    materials: Dict[str, Material]
    boundary_conditions: List[BoundaryCondition] = []
    meta: Meta

    model_config = {
        'validate_assignment': True,
        'populate_by_name': True,
        'extra': 'forbid'
    }

    @model_validator(mode='after')
    def check_references(cls, mesh):
        node_ids = {n.id for n in mesh.nodes}
        element_ids = {e.id for e in mesh.elements}
        for el in mesh.elements:
            for idx in el.node_indices:
                if idx not in node_ids:
                    raise ValueError(f'Element {el.id} references unknown node {idx}')
        for bc in mesh.boundary_conditions:
            if bc.element_id not in element_ids:
                raise ValueError(f'BoundaryCondition references unknown element {bc.element_id}')
        return mesh

