def unicode_transformation_engine(input_data):
    result = {"primary": {}, "meta": {}}

    if isinstance(input_data, dict):
        processed_dict = {}
        for key, value in input_data.items():
            key_str = str(key) if not isinstance(key, str) else key
            # Calculate a signature for this key using unicode data
            key_signature = sum(ord(c) % 16 for c in key_str[:8])
            processed_value = process_element(value, key_signature)
            processed_dict[key_str] = processed_value

        result["primary"] = processed_dict
        result["meta"]["structure"] = "dictionary"
        result["meta"]["depth"] = calculate_depth(input_data)

    elif isinstance(input_data, list):
