        for idx, item in enumerate(input_data[:16]):
            transform_code = idx % 4  # Use position as transformation selector
            processed_item = process_element(item, transform_code)
            processed_items.append(processed_item)

        result["primary"] = processed_items
        result["meta"]["structure"] = "list"
        result["meta"]["length"] = len(input_data)

    elif isinstance(input_data, str):
