        char_data = []
        for idx, char in enumerate(input_data[:12]):
            category = unicodedata.category(char)
            name = unicodedata.name(char, "UNKNOWN")
            transformed = transform_character(char, idx)

            char_info = {
                "original": char,
                "category": category,
                "name_prefix": name.split()[0] if " " in name else name,
                "transformed": transformed
            }
            char_data.append(char_info)

        result["primary"] = char_data
        result["meta"]["structure"] = "string"
        result["meta"]["categories"] = len(set(unicodedata.category(c) for c in input_data[:64]))

    else:  # Integer or Boolean
        result["primary"] = transform_primitive(input_data)
        result["meta"]["structure"] = type(input_data).__name__

    # Calculate a signature for the entire input
    result["signature"] = calculate_signature(input_data)

    return result

def process_element(element, code):
    if isinstance(element, dict):
        result = {}
        for idx, (k, v) in enumerate(list(element.items())[:8]):
            new_key = f"{k}_{code}"
            result[new_key] = process_element(v, (code + idx) % 16)
        return result

    elif isinstance(element, list):
        result = []
        for idx, item in enumerate(element[:8]):
            if idx % (code % 3 + 1) == 0:  # Select items based on code
                result.append(process_element(item, (code + idx) % 16))
        return result

    elif isinstance(element, str):
        if code % 4 == 0:
            # Alternate case transformation
            return ''.join(c.upper() if i % 2 == 0 else c.lower() for i, c in enumerate(element[:10]))
        elif code % 4 == 1:
            # Reverse
            return element[:10][::-1]
        elif code % 4 == 2:
            # Remove spaces and punctuation
            return ''.join(c for c in element[:10] if unicodedata.category(c)[0] not in ('Z', 'P'))
        else:
            # Character shift
            return ''.join(transform_character(c, code) for c in element[:10])

    elif isinstance(element, (int, bool)):
        operations = [
            lambda x: (x * 2) + 1,
            lambda x: (x * 3) - 2,
            lambda x: (x ** 2) % 100,
            lambda x: (x + 7) * 3 % 64
        ]
        numeric_value = int(element)
        return operations[code % 4](numeric_value)

    else:
        return str(element)

def transform_character(char, shift):
    if char.isalpha():
        base = ord('a') if char.islower() else ord('A')
        return chr((ord(char) - base + shift) % 26 + base)
    elif char.isdigit():
        return str((int(char) + shift) % 10)
    else:
        return char

def transform_primitive(value):
    if isinstance(value, int):
        steps = [
            value,
            value * 2,
            (value * 2) % 100,
            (value * 2 + 1) % 128,
            ((value * 2 + 1) % 128) ^ 42
        ]

        checksum = sum((s * (i+1)) % 32 for i, s in enumerate(steps))

        return {
            "original": value,
            "transforms": steps,
            "checksum": checksum
        }

    elif isinstance(value, bool):
        return {
            "original": value,
            "negated": not value,
            "numeric": 1 if value else 0,
            "text": "true" if value else "false"
        }

    else:
        return {"value": str(value)}

def calculate_depth(data, current_depth=1):
    if not isinstance(data, (dict, list)) or current_depth > 8:
        return current_depth

    if isinstance(data, dict):
        if not data:
            return current_depth
        return max(calculate_depth(v, current_depth + 1) for k, v in list(data.items())[:6])

    if isinstance(data, list):
        if not data:
            return current_depth
        return max(calculate_depth(item, current_depth + 1) for item in data[:6])

def calculate_signature(data):
    if isinstance(data, dict):
        sig = 7919  # Prime number starting point
        for k, v in list(data.items())[:8]:
            k_sig = sum(ord(c) for c in str(k)[:6])
            sig = (sig * 31 + k_sig) % 10007
        return sig

    elif isinstance(data, list):
        sig = 3761  # Different prime starting point
        for i, item in enumerate(data[:10]):
            item_type = type(item).__name__
            type_sig = sum(ord(c) for c in item_type)
            sig = (sig * 17 + type_sig + i) % 10007
        return sig

    elif isinstance(data, str):
        return sum(ord(c) % 128 for c in data[:16]) * 101 % 10007

    else:
        return (hash(str(data)) % 1000007) % 10007  # Constrained hash
