    model_validator, field_validator,
    StrictStr, StrictInt, StrictBool,
    conint, confloat, condecimal, PrivateAttr
)

class GearCategory(Enum):
    TENT = 'tent'
    STOVE = 'stove'
    LIGHTING = 'lighting'
    SLEEPING = 'sleeping'
    OTHER = 'other'

    @classmethod
    def _missing_(cls, value):
        raise ValidationError(f"Invalid GearCategory: {value}", model=cls)

class Dimension(BaseModel):
    length: confloat(gt=0)
    width: confloat(gt=0)
    height: confloat(gt=0)
    unit: Literal['cm', 'in']
    model_config = ConfigDict(extra='forbid')

class GPSLocation(BaseModel):
    lat: confloat(ge=-90, le=90)
    lon: confloat(ge=-180, le=180)
    model_config = ConfigDict(extra='forbid')

class PriceTier(BaseModel):
    name: StrictStr
    discount_pct: confloat(gt=0, le=100)
    model_config = ConfigDict(extra='forbid')

class SeasonRate(BaseModel):
    start: date
    end: date
    rate_per_day: condecimal(gt=0)
    model_config = ConfigDict(extra='forbid')

    @model_validator(mode='after')
    def check_interval(cls, m):
        if m.end <= m.start:
            raise ValidationError("SeasonRate.end must be after start", model=cls)
        return m

class InventoryRecord(BaseModel):
    last_rented: Optional[datetime] = None
    last_returned: Optional[datetime] = None
    available: StrictBool
    renter_count: conint(ge=0)
    model_config = ConfigDict(extra='forbid')

    @model_validator(mode='after')
    def check_dates(cls, m):
        if m.last_rented and m.last_returned and m.last_returned < m.last_rented:
            raise ValidationError("last_returned cannot precede last_rented", model=cls)
        return m

class RentalPolicy(BaseModel):
    min_days: conint(ge=1)
    max_days: conint(ge=1)
    deposit: condecimal(gt=0)
    seasonal_rates: Optional[List[SeasonRate]] = None
    discount_tiers: Optional[List[PriceTier]] = None
    model_config = ConfigDict(extra='forbid')

    @model_validator(mode='after')
    def check_policy(cls, m):
        if m.min_days > m.max_days:
            raise ValidationError("min_days must be <= max_days", model=cls)
        if m.seasonal_rates:
            seq = sorted(m.seasonal_rates, key=lambda x: x.start)
            for a, b in zip(seq, seq[1:]):
                if b.start <= a.end:
                    raise ValidationError("Overlapping SeasonRate intervals", model=cls)
        if m.discount_tiers:
            names = [d.name for d in m.discount_tiers]
            if len(names) != len(set(names)):
                raise ValidationError("Duplicate PriceTier names", model=cls)
        return m

class TentAttributes(BaseModel):
    kind: Literal['tent']
    capacity: conint(ge=1)
    seasonal_rating: Literal['3-season', '4-season']
    model_config = ConfigDict(extra='forbid')

class StoveAttributes(BaseModel):
    kind: Literal['stove']
    fuel_type: Literal['gas', 'liquid']
    max_output_watt: confloat(gt=0)
    model_config = ConfigDict(extra='forbid')

AttributesUnion = Annotated[
    Union[TentAttributes, StoveAttributes],
    Field(discriminator='kind')
]

class GearItem(BaseModel):
    name: StrictStr
    serial: StrictStr
    category: GearCategory
    weight_kg: confloat(gt=0)
    dimensions: Dimension
    location: GPSLocation
    inventory: InventoryRecord
    rental_policy: RentalPolicy
    attributes: AttributesUnion
    model_config = ConfigDict(extra='forbid')

    @field_validator('name')
    def name_not_blank(cls, v):
        if not v.strip():
            raise ValidationError("name cannot be blank", model=cls)
        return v

    @field_validator('serial')
    def serial_format(cls, v):
        if not re.match(r'^[A-Z0-9\-]+$', v):
            raise ValidationError("serial must be uppercase alphanum or hyphens", model=cls)
        return v

class GearKit(BaseModel):
    kit_id: Union[StrictStr, conint(gt=0)] = Field(alias='kitId')
    version: StrictInt = Field(1)
    name: StrictStr
    items: List[GearItem]
    created_at: datetime = Field(alias='createdAt')
    tags: Set[StrictStr] = Field(default_factory=set)
    total_weight: confloat(gt=0) = Field(alias='totalWeight')
    metadata: Optional[Dict[StrictStr, StrictStr]] = None
    description: Optional[StrictStr] = None
    location: GPSLocation
    _checksum: str = PrivateAttr()

    model_config = ConfigDict(
        extra='forbid',
        populate_by_name=True,
        json_loads=json.loads
    )

    @field_validator('name')
    def name_pattern(cls, v):
        if not re.fullmatch(r'[A-Za-z0-9 ]{3,50}', v):
            raise ValidationError("name must be 3-50 alphanumeric+spaces", model=cls)
        return v

    @field_validator('tags', mode='before')
    def uppercase_tags(cls, v):
        return {t.upper() for t in v}

    @model_validator(mode='after')
    def compute_and_check(cls, m):
        # checksum is kitId-version
        m._checksum = f"{m.kit_id}-{m.version}"
        # unique serials
        seq = [it.serial for it in m.items]
        if len(seq) != len(set(seq)):
            raise ValidationError("Duplicate serial numbers in items", model=cls)
        # weight match
        total = sum(it.weight_kg for it in m.items)
        if abs(total - m.total_weight) > Decimal('1e-6'):
            raise ValidationError(
                f"totalWeight {m.total_weight} != sum {total}", model=cls
            )
        # dates consistency
        for it in m.items:
            inv = it.inventory
            for dt in (inv.last_rented, inv.last_returned):
                if dt and dt < m.created_at:
                    raise ValidationError(
                        "inventory dates must not precede createdAt", model=cls
                    )
        # metadata values non-blank
        if m.metadata:
            for k, v in m.metadata.items():
                if not v.strip():
                    raise ValidationError("metadata values cannot be blank", model=cls)
        return m

