export function optimizeRoutes(input){
  const { retentionMatrix: R = [], distanceMatrix: D = [], creditScores: C = [] } = input || {};
  const n = D.length;
  const avgRetention = n && R[0]
    ? ~~(R.flat().reduce((a, b) => a + b, 0) / (n * R[0].length))
    : 0;
  const { scores: routeScores, best: bestStart } = (() => {
    const scArr = Array(n).fill().map((_, start) => {
      const used = new Set([start]);
      let rS = 0, dS = 0, cS = 0;
      (function traverse(u, step) {
        if (used.size === n) return;
        const [dMin, nxt] = D[u].reduce(
          ([md, mi], v, j) => (!used.has(j) && v < md ? [v, j] : [md, mi]),
          [Infinity, -1]
        );
        if (nxt < 0) return;
        used.add(nxt);
        rS += R[start]?.[step] || 0;
        dS += dMin;
        cS += C[nxt] || 0;
        traverse(nxt, step + 1);
      })(start, 0);
      return ((rS * 100) / (1 + dS) | 0) - cS;
    });
    const best = scArr.reduce((bi, _, i) => (scArr[i] > scArr[bi] ? i : bi), 0);
    return { scores: scArr, best };
  })();
  const creditSummary = C.reduce((acc, v) => {
    const key = v < 300 ? 'low' : v < 600 ? 'medium' : 'high';
    acc[key]++;
    return acc;
  }, { low: 0, medium: 0, high: 0 });
  return { routeScores, bestStart, avgRetention, creditSummary };
}
