    fn message_encoder(input: serde_json::Value) -> serde_json::Value {
    let input_obj = match input.as_object() {
        Some(obj) => obj,
        None => return serde_json::json!({"error": "Input must be an object"}),
    };

    let message = match input_obj.get("message").and_then(|v| v.as_str()) {
        Some(msg) => msg,
        None => return serde_json::json!({"error": "Message field must be a string"}),
    };

