    let mut idx = 0;
    for c in key.chars() {
        let val = c as u32 as i32;
        let row = idx / 8;
        let col = idx % 8;
        if row < 8 && col < 8 {
            matrix[row][col] = val % 128;
        }
        idx += 1;
        if idx >= 64 {
            break;
        }
    }

    // Fill remaining cells with derived values
    for i in idx..64 {
        let row = i / 8;
        let col = i % 8;
        let prev_row = if row > 0 { row - 1 } else { 7 };
        let prev_col = if col > 0 { col - 1 } else { 7 };
        matrix[row][col] = (matrix[prev_row][col] + matrix[row][prev_col]) % 128;
    }

