                    errors.append({'loc': base + ('refereeIds',), 'msg': f'referee {rid} not qualified for {g.sport}', 'type': 'value_error'})
        # week-game consistency
        total_week_games = sum(len(w.matches) for w in m.weeks)
        if total_week_games != len(m.games):
            errors.append({'loc': ('weeks',), 'msg': 'sum of week games must equal total games', 'type': 'value_error'})
        # no overlapping per venue
        by_venue: Dict[int, List[Game]] = {}
        for g in m.games:
            by_venue.setdefault(g.venue_id, []).append(g)
        for vid, gl in by_venue.items():
            gls = sorted(gl, key=lambda x: x.start_time)
            for prev, nxt in zip(gls, gls[1:]):
                if nxt.start_time < prev.end_time:
                    errors.append({'loc': ('games',), 'msg': f'overlap at venue {vid}', 'type': 'value_error'})
                    break
