        registers, memory, flags, stack = op_table[metamorphic_op](registers, memory, metamorphic_addr, flags, stack)

        # Post-processing: Apply entropy to system state
        if cycle_count % 7 == 0 and len(stack) > 0:
            # Occasionally modify memory based on stack
            memory[cycle_count % len(memory)] ^= stack[-1] % 256

        # Auto-mutate registers based on flags
        if flags["zero"] and flags["carry"]:
            registers["X"] = (registers["X"] + 1) % 256
        if flags["overflow"] and flags["negative"]:
            registers["Y"] = (registers["Y"] - 1) % 256

        cycle_count += 1

        # Snapshot memory state according to original pattern
        if (step + 1) % 4 == 0 or step == len(operations) - 1:
            # Only store the first 8 elements to maintain compatibility
            result["memory"].append(memory[:8].copy())

    # Final state calculation with original format
    result["registers"] = {k: registers[k] for k in ["A", "B", "C", "D"]}

    # Calculate output with similar formula but more factors
    memory_contribution = sum(memory[:8])
    register_contribution = registers["A"]
    stack_factor = sum(stack) % 8 if stack else 0
    flag_impact = sum(2**i for i, f in enumerate(flags.values()) if f) % 4

    result["output"] = memory_contribution + register_contribution + stack_factor + flag_impact

