fn extract_cipher_key(input: &serde_json::Value) -> Vec<u8> {
    let mut key = Vec::with_capacity(8);

    if let Some(obj) = input.as_object() {
        // Generate key from object structure
        let keys_xor = obj.keys().fold(0u8, |acc, k| acc ^ (k.len() as u8));
        key.push(keys_xor);

        // Process string values
        let str_val = obj.values()
            .filter_map(|v| v.as_str())
            .flat_map(|s| s.bytes())
            .take(4)
            .fold(0u8, |acc, b| acc.wrapping_add(b));
        key.push(str_val);
    }

    if let Some(arr) = input.as_array() {
        key.push(arr.len() as u8);

        // Process numbers in array
        let num_sum = arr.iter()
            .filter_map(|v| v.as_i64())
            .take(8)
            .fold(0i64, |acc, n| acc.wrapping_add(n));
        key.push((num_sum & 0xFF) as u8);
    }

    // Ensure we have at least 4 elements
    if key.is_empty() {
        key = vec![13, 37, 42, 97];
    }

    // Expand key if needed
    while key.len() < 4 {
        let last = *key.last().unwrap_or(&42);
        key.push(last.wrapping_mul(17).wrapping_add(11));
    }

    key
}

fn transform_document(value: serde_json::Value, key: &[u8], depth: usize) -> serde_json::Value {
    let k = key[depth % key.len()];

    match value {
        serde_json::Value::Null => serde_json::Value::Null,

        serde_json::Value::Bool(b) => {
            serde_json::Value::Bool(if (k & 1) != 0 { !b } else { b })
        },

        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                let op = (k >> (depth % 3)) & 0x7;
                let k_val = k as i64;

                let result = match op {
                    0 => i.wrapping_add(k_val),
                    1 => i.wrapping_sub(k_val),
                    2 => i.wrapping_mul((k_val % 10).max(1)),
                    3 => i ^ k_val,
                    4 => (i << (k_val % 7)) | (i >> (64 - (k_val % 7))),
                    5 => !i,
                    6 => -i,
                    _ => (i + k_val) % 997,
                };

                if let Some(num) = serde_json::Number::from_f64(result as f64) {
                    serde_json::Value::Number(num)
                } else {
                    serde_json::Value::Number(n)
                }
            } else {
                serde_json::Value::Number(n)
            }
        },

        serde_json::Value::String(s) => {
            let cipher_op = k % 4;

            let transformed = match cipher_op {
                0 => { // Caesar-like cipher
                    s.chars()
                        .map(|c| {
                            if c.is_ascii_alphabetic() {
                                let base = if c.is_ascii_lowercase() { b'a' } else { b'A' };
                                let offset = ((c as u8 - base + k) % 26) + base;
                                offset as char
                            } else { c }
                        })
                        .collect()
                },
                1 => { // Reverse
                    s.chars().rev().collect()
                },
                2 => { // Character substitution
                    s.chars()
                        .enumerate()
                        .map(|(i, c)| {
                            if c.is_ascii_alphanumeric() {
                                let shift = key[(depth + i) % key.len()] % 26;
                                if c.is_ascii_alphabetic() {
                                    let base = if c.is_ascii_lowercase() { b'a' } else { b'A' };
                                    let offset = ((c as u8 - base + shift) % 26) + base;
                                    offset as char
                                } else {
                                    let base = b'0';
                                    let offset = ((c as u8 - base + shift) % 10) + base;
                                    offset as char
                                }
                            } else { c }
                        })
                        .collect()
                },
                _ => { // XOR selected characters
                    s.chars()
                        .enumerate()
                        .map(|(i, c)| {
                            if i % 2 == (k % 2) as usize {
                                let xor_val = (c as u8) ^ key[(depth + i) % key.len()];
                                xor_val as char
                            } else { c }
                        })
                        .collect()
                }
            };

            serde_json::Value::String(transformed)
        },

        serde_json::Value::Array(arr) => {
            let mut result = Vec::with_capacity(arr.len());

            for (i, item) in arr.into_iter().enumerate().take(16) {
                result.push(transform_document(item, key, depth + i + 1));
            }

            // Array transformations based on key
            if (k & 4) != 0 && result.len() > 1 {
                result.reverse();
            }

            if (k & 8) != 0 && result.len() > 1 {
                // Rotate array
                let rot = (k as usize) % result.len();
                result.rotate_left(rot);
            }

            serde_json::Value::Array(result)
        },

        serde_json::Value::Object(obj) => {
            let mut result = serde_json::Map::new();

            for (k_str, v) in obj {
                // Transform key based on cipher_key
                let new_key = if (k & 16) != 0 {
                    k_str.chars().rev().collect()
                } else {
                    k_str
                };

                // Recursively transform value
                let new_val = transform_document(v, key, depth + 1);
                result.insert(new_key, new_val);
            }

            serde_json::Value::Object(result)
        },
    }
}

