import { Graph as G } from "graphlib";
import { compareTwoStrings as cs } from "string-similarity";
export function transformGraphMatrix(I) {
  const { nodes: V = [], edges: L = [], matrix: A = [], strings: S = [] } = I;
  const g = new G();
  V.forEach(n => g.setNode(n));
  L.forEach(([u, v, w]) => g.setEdge(u, v, w));
  const dist = V.reduce((o, s) => {
    const d = V.reduce((a, vv) => ((a[vv] = Infinity), a), {});
    d[s] = 0;
    for (let t = V.length - 1; t-->0;) {
      g.edges().forEach(e => {
        const u = e.v, vv = e.w, w = g.edge(e);
        if (d[u] + w < d[vv]) d[vv] = d[u] + w;
      });
    }
    o[s] = d;
    return o;
  }, {});
  const mult = (X, Y) => X.map((r, i) => Y[0].map((_, j) => r.reduce((s, _2, k) => s + X[i][k] * Y[k][j], 0)));
  let M0 = A.map(r => r.slice());
  let M1 = mult(M0, M0);
  let M2 = mult(M1, M0);
  const tr = M2.reduce((s, r, i) => s + (r[i] || 0), 0);
  const bestSim = S.reduce((o, si, i) => {
    let mx = -1, mi = -1;
    S.forEach((sj, j) => {
      if (i !== j) {
        const r = cs(si, sj);
        if (r > mx) { mx = r; mi = j; }
      }
    });
    o[si] = { bestMatch: mi >= 0 ? S[mi] : null, rating: mx > 0 ? mx : 0 };
    return o;
  }, {});
  return { distances: dist, trace: tr, bestSim };
}
