    use serde_json::{Value, from_str, to_string, Map, json};
    use std::io::{self, Read};

    fn route_optimizer(input: serde_json::Value) -> serde_json::Value {
    use serde_json::{json, Value};

    let network = match &input["network"] {
        Value::Object(obj) => obj.clone(),
        _ => return json!({"error": "Invalid network"}),
    };

    let start = match &input["start"] {
        Value::String(s) => s.clone(),
        _ => return json!({"error": "Invalid start node"}),
    };

    let end = match &input["end"] {
        Value::String(s) => s.clone(),
        _ => return json!({"error": "Invalid end node"}),
    };

    let encryption_key = match &input["encryption_key"] {
        Value::Array(arr) => arr.clone(),
        _ => vec![json!(1), json!(2), json!(3), json!(4)],
    };

    // Convert encryption key to a matrix
    let mut key_matrix = [[0u32; 4]; 4];
    for (i, row) in key_matrix.iter_mut().enumerate().take(4) {
        for (j, cell) in row.iter_mut().enumerate().take(4) {
            let idx = i * 4 + j;
            if idx < encryption_key.len() {
                if let Value::Number(n) = &encryption_key[idx] {
                    if let Some(num) = n.as_u64() {
                        *cell = num as u32;
                    }
                }
            }
            // Ensure no zeros in the matrix
            if *cell == 0 {
                *cell = (i as u32 + 1) ^ (j as u32 + 1);
            }
        }
    }

    // Find all possible paths from start to end with at most 8 nodes
    let mut all_paths = Vec::new();
    find_paths(&network, &start, &end, &mut Vec::new(), &mut all_paths, 0, 8);

    // Score and encode each path
    let mut scored_paths = Vec::new();
    for path in all_paths {
        let path_cost = calculate_path_cost(&path, &network);
        let encoded_path = encode_path(&path, &key_matrix);
        let path_signature = calculate_path_signature(&path, &key_matrix);

        scored_paths.push(json!({
            "path": path,
            "encoded": encoded_path,
            "cost": path_cost,
            "signature": path_signature
        }));
    }

    // Sort paths by cost
    scored_paths.sort_by(|a, b| {
        let a_cost = a["cost"].as_i64().unwrap_or(i64::MAX);
        let b_cost = b["cost"].as_i64().unwrap_or(i64::MAX);
        a_cost.cmp(&b_cost)
    });

    // Return optimal route information
    json!({
        "optimal_routes": scored_paths,
        "route_count": scored_paths.len(),
        "encryption_matrix": key_matrix.iter().map(|row| 
            json!(row.iter().map(|&x| json!(x)).collect::<Vec<_>>())
        ).collect::<Vec<_>>(),
        "metadata": {
            "matrix_determinant": calculate_matrix_determinant(&key_matrix),
            "network_complexity": network.len(),
            "optimization_level": calculate_optimization_level(&scored_paths)
        }
    })
}

fn find_paths(
    network: &serde_json::Map<String, serde_json::Value>,
    current: &str,
    end: &str,
    path_so_far: &mut Vec<String>,
    all_paths: &mut Vec<Vec<String>>,
    depth: usize,
    max_depth: usize
) {
    // Add current node to path
    path_so_far.push(current.to_string());

    // If we reached the destination, add the path to our results
    if current == end {
        all_paths.push(path_so_far.clone());
    } else if depth < max_depth {
        // Try all neighbors
        if let Some(serde_json::Value::Object(neighbors)) = network.get(current) {
            for (neighbor, _) in neighbors {
                // Avoid cycles in the path
                if !path_so_far.contains(&neighbor.to_string()) {
                    find_paths(network, neighbor, end, path_so_far, all_paths, depth + 1, max_depth);
                }
            }
        }
    }

    // Backtrack
    path_so_far.pop();
}

fn calculate_path_cost(path: &[String], network: &serde_json::Map<String, serde_json::Value>) -> i64 {
    let mut total_cost = 0;

    for i in 0..path.len() - 1 {
        let current = &path[i];
        let next = &path[i + 1];

        if let Some(serde_json::Value::Object(neighbors)) = network.get(current) {
            if let Some(serde_json::Value::Number(cost)) = neighbors.get(next) {
                total_cost += cost.as_i64().unwrap_or(0);
            }
        }
    }

    total_cost
}

fn encode_path(path: &[String], key_matrix: &[[u32; 4]; 4]) -> String {
    let mut encoded = String::new();

    for (i, node) in path.iter().enumerate() {
        let row = i % 4;
        let mut node_code = 0u32;

        for (j, ch) in node.chars().enumerate().take(8) {
            let col = j % 4;
            let char_val = ch as u32;
            node_code = node_code.wrapping_add(char_val ^ key_matrix[row][col]);
        }

        encoded.push_str(&format!("{:X}", node_code % 16));
    }

    encoded
}

fn calculate_path_signature(path: &[String], key_matrix: &[[u32; 4]; 4]) -> u32 {
    let mut signature = 0u32;

    for (i, node) in path.iter().enumerate() {
        let row = i % 4;
        for (j, ch) in node.chars().enumerate() {
            let col = j % 4;
            let char_val = ch as u32;
            signature = signature.wrapping_add(char_val);
            signature = signature ^ key_matrix[row][col];
            signature = signature.wrapping_mul(17);
        }
    }

    signature
}

fn calculate_matrix_determinant(matrix: &[[u32; 4]; 4]) -> i64 {
    // For simplicity, we'll approximate the determinant with the sum of diagonals
    let mut det = 0i64;

    // Main diagonal product
    let mut diag1 = 1i64;
    for i in 0..4 {
        diag1 = diag1.wrapping_mul(matrix[i][i] as i64);
    }

    // Secondary diagonal product
    let mut diag2 = 1i64;
    for i in 0..4 {
        diag2 = diag2.wrapping_mul(matrix[i][3-i] as i64);
    }

    det = diag1 - diag2;
    det
}

fn calculate_optimization_level(paths: &[serde_json::Value]) -> u32 {
    if paths.is_empty() {
        return 0;
    }

    let min_cost = paths[0]["cost"].as_i64().unwrap_or(0);
    let mut complexity = 0u32;

    for path in paths {
        let path_cost = path["cost"].as_i64().unwrap_or(0);
        let path_len = path["path"].as_array().map_or(0, |arr| arr.len()) as u32;

        complexity = complexity.wrapping_add((path_cost - min_cost) as u32);
        complexity = complexity.wrapping_add(path_len * 10);
    }

    (complexity % 100) + 1
}

