from datetime import datetime
import re

class Severity(Enum):
    LOW = 'low'
    MEDIUM = 'medium'
    HIGH = 'high'
    CRITICAL = 'critical'

class Likelihood(Enum):
    RARE = 'rare'
    OCCASIONAL = 'occasional'
    FREQUENT = 'frequent'
    CERTAIN = 'certain'

class ComponentType(Enum):
    SENSOR = 'sensor'
    ACTUATOR = 'actuator'
    CONTROLLER = 'controller'
    NETWORK = 'network'

class Protocol(Enum):
    TCP = 'tcp'
    UDP = 'udp'
    MQTT = 'mqtt'
    HTTP = 'http'

class MitigationStatus(Enum):
    PLANNED = 'planned'
    IN_PROGRESS = 'in_progress'
    COMPLETED = 'completed'

class Mitigation(BaseModel):
    mitigation_id: StrictStr = Field(..., alias='id')
    description: StrictStr
    status: MitigationStatus
    cost: StrictFloat
    effected_component: Optional[StrictStr] = Field(None, alias='component')

    model_config = ConfigDict(extra='forbid')

    @model_validator(mode='after')
    def sanity_checks(cls, m):
        errors = []
        if m.cost < 0:
            errors.append({'loc': ('cost',), 'msg': 'cost must be non-negative', 'type': 'value_error'})
        if m.status == MitigationStatus.COMPLETED and m.effected_component is None:
            errors.append({'loc': ('component',), 'msg': 'completed mitigation must reference effected component', 'type': 'value_error'})
        if errors:
            raise ValidationError(errors, model=cls)
        return m

class InternalSource(BaseModel):
    type: Literal['internal']
    department: StrictStr
    detected_at: datetime

    model_config = ConfigDict(extra='forbid')

class ExternalSource(BaseModel):
    type: Literal['external']
    vendor: StrictStr
    report_reference: StrictStr

    model_config = ConfigDict(extra='forbid')

RiskSource = Union[InternalSource, ExternalSource]

class Risk(BaseModel):
    risk_id: StrictStr
    description: StrictStr
    severity: Severity
    likelihood: Likelihood
    source_info: RiskSource = Field(..., alias='source')
    mitigations: List[Mitigation]

    model_config = ConfigDict(extra='forbid')

    @model_validator(mode='after')
    def validate_risk(cls, r):
        errors = []
        if r.severity == Severity.CRITICAL and r.likelihood == Likelihood.RARE:
            errors.append({'loc': ('severity', 'likelihood'), 'msg': 'critical severity cannot have rare likelihood', 'type': 'value_error'})
        if r.severity in (Severity.HIGH, Severity.CRITICAL) and not r.mitigations:
            errors.append({'loc': ('mitigations',), 'msg': 'high or critical risks must have mitigations', 'type': 'value_error'})
        ids = [m.mitigation_id for m in r.mitigations]
        if len(ids) != len(set(ids)):
            errors.append({'loc': ('mitigations',), 'msg': 'mitigation ids must be unique', 'type': 'value_error'})
        if errors:
            raise ValidationError(errors, model=cls)
        return r

class Connection(BaseModel):
    target: StrictStr
    protocol: Protocol
    bandwidth: StrictInt
    secure: StrictBool

    model_config = ConfigDict(extra='forbid')

    @model_validator(mode='after')
    def validate_connection(cls, c):
        if c.bandwidth <= 0:
            raise ValidationError([
                {'loc': ('bandwidth',), 'msg': 'bandwidth must be >0', 'type': 'value_error'}
            ], model=cls)
        return c

class AttackChain(BaseModel):
    steps: List[StrictStr]
    chain_score: StrictFloat
    last_updated: datetime

    model_config = ConfigDict(extra='forbid')

    @model_validator(mode='after')
    def validate_chain(cls, a):
        errors = []
        if len(a.steps) < 2:
            errors.append({'loc': ('steps',), 'msg': 'attack chain must have at least two steps', 'type': 'value_error'})
        if a.chain_score < 0:
            errors.append({'loc': ('chain_score',), 'msg': 'chain_score must be non-negative', 'type': 'value_error'})
        if errors:
            raise ValidationError(errors, model=cls)
        return a

class Component(BaseModel):
    name: StrictStr
    type: ComponentType
    risks: List[Risk]
    connections: Optional[List[Connection]] = None
    attack_chains: Optional[List[AttackChain]] = None
    tags: Optional[List[StrictStr]] = None

    model_config = ConfigDict(extra='forbid')

    @model_validator(mode='after')
    def validate_component(cls, comp):
        errors = []
        risk_ids = [r.risk_id for r in comp.risks]
        if len(risk_ids) != len(set(risk_ids)):
            errors.append({'loc': ('risks',), 'msg': 'risk ids must be unique', 'type': 'value_error'})
        if comp.tags:
            if len(comp.tags) != len(set(comp.tags)):
                errors.append({'loc': ('tags',), 'msg': 'tags must be unique', 'type': 'value_error'})
        if comp.connections:
            for conn in comp.connections:
                if conn.target == comp.name:
                    errors.append({'loc': ('connections',), 'msg': 'component cannot connect to itself', 'type': 'value_error'})
        if errors:
            raise ValidationError(errors, model=cls)
        return comp

class MatrixMetadata(BaseModel):
    version: StrictStr
    generated_at: datetime
    author: StrictStr

    model_config = ConfigDict(extra='forbid')

    @model_validator(mode='after')
    def validate_meta(cls, m):
        if not re.match(r'^\d+\.\d+\.\d+$', m.version):
            raise ValidationError([
                {'loc': ('version',), 'msg': 'version must be semantic (X.Y.Z)', 'type': 'value_error'}
            ], model=cls)
        return m

class ThreatMatrix(BaseModel):
    components: Dict[StrictStr, Component]
    metadata: MatrixMetadata

    model_config = ConfigDict(extra='forbid')

    @model_validator(mode='before')
    def check_components_nonempty(cls, data):
        comps = data.get('components')
        if not comps or not isinstance(comps, dict):
            raise ValidationError([
                {'loc': ('components',), 'msg': 'components must be a non-empty dict', 'type': 'value_error'}
            ], model=cls)
        return data

    @model_validator(mode='after')
    def validate_topology(cls, m):
        errors = []
        names = set(m.components.keys())
        for name, comp in m.components.items():
            if comp.name != name:
                errors.append({'loc': ('components', name), 'msg': 'component key must match its name', 'type': 'value_error'})
            if comp.connections:
                for conn in comp.connections:
                    if conn.target not in names:
                        errors.append({'loc': ('components', name, 'connections'), 'msg': f"unknown target {conn.target}", 'type': 'value_error'})
                    else:
                        rev = m.components[conn.target].connections or []
                        if not any(rc.target == name for rc in rev):
                            errors.append({'loc': ('components', name, 'connections'), 'msg': f"missing reverse connection from {conn.target}", 'type': 'value_error'})
        if errors:
            raise ValidationError(errors, model=cls)
        return m

