def analyze_task_dependencies(config):
    tasks = {}
    if isinstance(config, dict):
        tasks = config.get("tasks", config)
    elif isinstance(config, int):
        n = min(config, 8)
        tasks = {f"T{i}": {"duration": i+1, "deps": [f"T{i-1}"] if i > 0 else []} for i in range(n)}
    elif isinstance(config, str):
        chars = list(config[:8])
        tasks = {c: {"duration": ord(c) % 10 + 1, "deps": [chars[i-1]] if i > 0 else []} 
                for i, c in enumerate(chars)}
    elif isinstance(config, list):
        items = config[:8]
        tasks = {f"T{i}": {"duration": item if isinstance(item, int) else len(str(item)), 
                          "deps": [f"T{i-1}"] if i > 0 else []} 
                for i, item in enumerate(items)}

    visited = set()
    topo_order = []

    def dfs(task_id):
        if task_id in visited:
            return
        visited.add(task_id)
        for dep in tasks.get(task_id, {}).get("deps", []):
            if dep in tasks:
                dfs(dep)
        topo_order.append(task_id)

    for task_id in tasks:
        if task_id not in visited:
            dfs(task_id)

    earliest_start = {}
    earliest_finish = {}

    for task_id in topo_order:
        max_dep_finish = 0
        for dep in tasks.get(task_id, {}).get("deps", []):
            if dep in earliest_finish:
                max_dep_finish = max(max_dep_finish, earliest_finish[dep])

        earliest_start[task_id] = max_dep_finish
        earliest_finish[task_id] = max_dep_finish + tasks[task_id].get("duration", 0)

    project_end = max(earliest_finish.values()) if earliest_finish else 0

    rev_deps = {t: [] for t in tasks}
    for t, info in tasks.items():
        for dep in info.get("deps", []):
            if dep in rev_deps:
                rev_deps[dep].append(t)

    latest_finish = {}
    latest_start = {}

    for t in reversed(topo_order):
        if not rev_deps[t]:
            latest_finish[t] = project_end
        else:
            latest_finish[t] = min(latest_start[succ] for succ in rev_deps[t] 
                                  if succ in latest_start)

        latest_start[t] = latest_finish[t] - tasks[t].get("duration", 0)

    slack = {t: latest_start.get(t, 0) - earliest_start.get(t, 0) for t in tasks}
    critical_path = [t for t, s in slack.items() if s == 0]

    def compute_slice(seed_tasks, direction):
        result = set(seed_tasks)
        queue = list(seed_tasks)

        while queue:
            current = queue.pop(0)
            if direction == "forward":
                next_tasks = rev_deps.get(current, [])
            else:
                next_tasks = tasks.get(current, {}).get("deps", [])

            for next_task in next_tasks:
                if next_task in tasks and next_task not in result:
                    result.add(next_task)
                    queue.append(next_task)

        return sorted(list(result))

    timeline = []
    active_tasks = set()

    time_points = sorted(set(list(earliest_start.values()) + 
                            list(earliest_finish.values())))

    for time in time_points[:5]:
        starting = [t for t, start in earliest_start.items() if start == time]
        finishing = [t for t, finish in earliest_finish.items() if finish == time]

        for t in starting:
            active_tasks.add(t)
        for t in finishing:
            if t in active_tasks:
                active_tasks.remove(t)

        timeline.append({
            "time": time,
            "start": starting,
            "finish": finishing,
            "active": sorted(list(active_tasks))
        })

    result = {
        "project_duration": project_end,
        "critical_path": critical_path[:5],
        "schedule": {t: {"start": earliest_start[t], 
                         "finish": earliest_finish[t], 
                         "slack": slack[t]} 
                    for t in list(tasks.keys())[:5]},
        "forward_slice": compute_slice(critical_path[:1], "forward") if critical_path else [],
        "backward_slice": compute_slice(critical_path[-1:], "backward") if critical_path else [],
        "timeline": timeline
    }

    return result
