export function computeWinProb(input){
  const hs=input.homeScore|0;
  const as=input.awayScore|0;
  const time=input.timeLeft|0;
  const offH=+input.homeOffEff;
  const offA=+input.awayOffEff;
  const maxPoss=Math.min(16,Math.floor(time/24));
  const p2=offH/(offH+offA);
  const p3=0.35*p2;
  const p1=0.2*(1-p2);
  const p0=1-p1-p2-p3;
  const ps=[p0,p1,p2,p3];
  const offset=16;
  let curr=new Array(33).fill(0);
  curr[(hs-as)+offset]=1;
  let next=new Array(33).fill(0);
  for(let n=1;n<=maxPoss;n++){
    next.fill(0);
    for(let d=-16;d<=16;d++){
      const i=d+offset;
      const pr=curr[i];
      if(pr>0){
        for(let k=0;k<=3;k++){
          const nd=d+k;
          const ni=nd+offset;
          if(ni>=0&&ni<33) next[ni]+=pr*ps[k];
          else if(nd>16) next[32]+=pr*ps[k];
          else if(nd<-16) next[0]+=pr*ps[k];
        }
      }
    }
    curr=next.slice();
  }
  let wp=0;
  for(let d=1;d<=16;d++) wp+=curr[d+offset];
  wp+=0.5*curr[offset];
  return {winProbability:wp};
}
