export function computePaths({adj: A, steps: K}) {
  const n = A.length;
  const mult = (X, Y) =>
    Array.from({ length: n }, (_, i) =>
      Array.from({ length: n }, (_, j) =>
        X[i].reduce((s, v, t) => s + v * Y[t][j], 0)
      )
    );
  let R = Array.from({ length: n }, (_, i) =>
    Array.from({ length: n }, (_, j) => (i === j ? 1 : 0))
  );
  let B = A.map(row => row.slice());
  let k = K;
  while (k > 0) {
    if (k & 1) R = mult(R, B);
    B = mult(B, B);
    k >>= 1;
  }
  const sum = R.reduce((t, r) => t + r.reduce((u, v) => u + v, 0), 0);
  const diag = R.map((r, i) => r[i]);
  return { matrix: R, sum, diag };
}
