class ScheduleDay(BaseModel):
    date: date
    sections: List[ScheduleSection]

    model_config = ConfigDict(extra="forbid")

    @model_validator(mode="after")
    def no_overlap(cls, m):
        intervals_by_team: Dict[UUID, List[tuple[datetime, datetime]]] = {}
        for sec in m.sections:
            for g in sec.games:
                for team in (g.home_team, g.away_team):
                    intervals_by_team.setdefault(team, []).append((g.start_time, g.end_time))
        for team, ivs in intervals_by_team.items():
            ivs_sorted = sorted(ivs, key=lambda x: x[0])
            for prev, curr in zip(ivs_sorted, ivs_sorted[1:]):
                if curr[0] < prev[1]:
                    raise ValidationError([{"loc": ("sections",), "msg": f"overlap for team {team}", "type": "value_error"}], cls)
        return m

