        return m

class SeasonSchedule(BaseModel):
    id: UUID = Field(default_factory=uuid4)
    league_name: str
    level: LeagueLevel
    season_start: date
    season_end: date
    teams: List[Team]
    players: List[Player]
    venues: List[Venue]
    referees: List[Referee]
    schedule: List[WeeklySchedule]
    playoffs: List[PlayoffRound]
    stats: Dict[UUID, TeamStats]

    model_config = ConfigDict(extra="forbid")

    @model_validator(mode="after")
    def check_consistency(cls, m):
        if m.season_end < m.season_start:
            raise ValidationError([{"loc": ("season_end",), "msg": "season_end before start", "type": "value_error"}], cls)
        team_ids = {t.id for t in m.teams}
        player_teams = {p.team_id for p in m.players}
        if not player_teams.issubset(team_ids):
            raise ValidationError([{"loc": ("players",), "msg": "player with unknown team", "type": "value_error"}], cls)
        venue_ids = {v.id for v in m.venues}
        for ws in m.schedule:
            for d in ws.days:
                if d.date < m.season_start or d.date > m.season_end:
                    raise ValidationError([{"loc": ("schedule",), "msg": "game date out of season", "type": "value_error"}], cls)
                for sec in d.sections:
                    for g in sec.games:
                        if g.home_team not in team_ids or g.away_team not in team_ids:
                            raise ValidationError([{"loc": ("schedule",), "msg": "game refers to unknown team", "type": "value_error"}], cls)
                        if g.venue not in venue_ids:
                            raise ValidationError([{"loc": ("schedule",), "msg": "game refers to unknown venue", "type": "value_error"}], cls)
        if set(m.stats.keys()) != team_ids:
            raise ValidationError([{"loc": ("stats",), "msg": "stats keys mismatch teams", "type": "value_error"}], cls)
        return m

